INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1432', 'spa', 'Gratuitamente, sin costo ni pago; también sin causa o motivo; o en vano, sin propósito.', 'Adverbio derivado del sustantivo que significa ''don'' (δωρεά), cuya idea central es algo dado sin esperar nada a cambio. En la mayoría de sus usos neotestamentarios significa ''gratuitamente'' o ''sin cobrar'', como cuando Jesús dice a sus discípulos que den gratis lo que gratis recibieron (Mt 10:8), o cuando Pablo declara que los creyentes son justificados gratuitamente por la gracia de Dios (Ro 3:24). Sin embargo, en Juan 15:25 adquiere el sentido de ''sin causa'' — me aborrecieron sin motivo —, mientras que en Gálatas 2:21 adopta el matiz de ''en vano'', indicando que la muerte de Cristo habría sido inútil si la justicia viniera por la ley.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1433', 'spa', 'conceder gratuitamente, otorgar, dar como regalo; enfatizando la naturaleza graciosa e inmerecida del don', 'El verbo δωρέω (de δῶρον, ''don, regalo'') significa dar libremente u obsequiar, enfatizando a menudo la gracia por encima de la obligación. En el Nuevo Testamento aparece en contextos de generosa concesión: Pilato entregando el cuerpo de Jesús a José, y Dios otorgando a los creyentes todo lo necesario para la vida y la piedad. La familia léxica subraya el carácter gratuito del verdadero dar: no es pago ni intercambio, sino puro don.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1434', 'spa', 'don, regalo dado libremente', 'Este sustantivo neutro denota un don o regalo, enfatizando la naturaleza de algo otorgado libremente. Pablo lo usa en Romanos 5:16 para describir el don gratuito de Dios en contraste con el juicio, mientras que Santiago 1:17 habla de toda buena dádiva y todo don perfecto que desciende del Padre de las luces. La palabra resalta la gracia del dador más que cualquier mérito en el receptor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1435', 'spa', 'Don u ofrenda, especialmente uno presentado en el altar del templo o entregado en honor y adoracion. Designa un regalo u ofrenda que abarca contextos ', 'Don u ofrenda, especialmente uno presentado en el altar del templo o entregado en honor y adoracion. Designa un regalo u ofrenda que abarca contextos tanto sagrados como honorificos. Los Magos traen δῶρα al nino Jesus (Mt 2:11), mientras que en el Sermon del Monte, Jesus instruye al adorador a dejar su δῶρον en el altar y primero reconciliarse con su hermano (Mt 5:23-24), un pasaje que influyo en la practica liturgica cristiana primitiva. La palabra tambien cubre la ofrenda al tesoro del templo que Jesus critica cuando los fariseos declaran bienes como ''Corban, es decir, ofrenda dedicada a Dios'' (Mt 15:5; Mr 7:11). En Hebreos, δῶρα aparece junto a θυσίαι como la formula estandar para ofrendas sacerdotales (Heb 5:1; 8:3-4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1436', 'spa', '¡Ah! Exclamación que expresa sorpresa, reconocimiento, temor o protesta; una interjección', 'Exclamación o interjección que expresa una emoción repentina: sorpresa, reconocimiento, temor o protesta. En Lucas 4:34, el hombre poseído por un demonio clama ''¡Ah! ¿Qué tenemos que ver contigo, Jesús de Nazaret?'' La partícula suele introducir un desafío o expresar alarma. Es el equivalente verbal de una reacción de sobresalto. Los espíritus demoniacos la usan frecuentemente en los Evangelios cuando se enfrentan a Jesús, reconociendo su identidad y autoridad mientras protestan contra su intervención. Es un estallido involuntario que revela perturbación interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1437', 'spa', 'Si, en caso de que — partícula condicional que introduce cláusulas hipotéticas o potenciales (con subjuntivo)', 'Ἐάν es la conjunción condicional griega estándar que se combina con el modo subjuntivo para presentar una situación como posible pero aún no realizada. Se distingue del simple εἰ (con indicativo) porque deja el resultado genuinamente abierto. A lo largo de 339 apariciones en el NT, estructura las enseñanzas de Jesús (''si alguno quiere venir en pos de mí'', Mt 16:24), la exhortación apostólica y condiciones de tipo legal. En español se traduce invariablemente como ''si'', aunque el matiz subjuntivo griego añade una contingencia que el simple ''si'' castellano no siempre refleja.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1438', 'spa', 'Pronombre reflexivo: a sí mismo/a, de sí mismo/a; también posesivo (su propio) y recíproco (unos a otros)', 'El pronombre reflexivo de tercera persona ἑαυτοῦ es una herramienta gramatical esencial del griego, que dirige la acción del verbo de vuelta sobre el sujeto. En el Nuevo Testamento aparece en todas las personas y números: ''niéguese a sí mismo'' (Mt 16:24), ''se humille'' (Mt 18:4). A veces adquiere valor posesivo (''sus propios muertos'', Mt 8:22) y ocasionalmente sentido recíproco (''entre sí'', Mt 27:35). El español refleja esta versatilidad con ''a sí mismo'' para el reflexivo directo, ''su propio'' para el posesivo y ''unos a otros'' para el recíproco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1439', 'spa', 'Permitir, dejar, consentir — conceder permiso o abstenerse de impedir; dejar en paz. El verbo ἐάω (eao) significa permitir, dejar o consentir que algo', 'Permitir, dejar, consentir — conceder permiso o abstenerse de impedir; dejar en paz. El verbo ἐάω (eao) significa permitir, dejar o consentir que algo suceda, con un matiz extendido de dejar a alguien en paz. Jesús no permitía que los demonios hablasen (Lucas 4:41). En su arresto dice ''Dejad, basta ya'' (Lucas 22:51). El Espíritu ''no les permitió'' a Pablo entrar en Bitinia (Hechos 16:7), y Dios ''permitió que todas las naciones anduvieran en sus propios caminos'' en generaciones pasadas (Hechos 14:16). El dueño de casa ''no habría permitido'' que entrasen a robar si hubiera sabido (Mateo 24:43).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1440', 'spa', 'Setenta; el número cardinal usado para grupos de personas, edades o cantidades', 'El numeral indeclinable «setenta», cargado de rica resonancia bíblica. Jesús designa a setenta (o setenta y dos) discípulos y los envía (Lucas 10:1, 17), evocando a los setenta ancianos de Israel. Esteban recuerda las setenta y cinco almas que descendieron a Egipto con Jacob (Hechos 7:14). El número aparece también en la logística militar: setenta jinetes escoltan a Pablo desde Jerusalén (Hechos 23:23), y en el recuento de pasajeros de un barco con 276 personas (Hechos 27:37, como parte del número compuesto). Cada lengua lo traduce de forma transparente: español «setenta», francés «soixante-dix», preservando el peso simbólico del número.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1441', 'spa', 'Setenta veces, adverbio numérico que indica repetición setenta veces', 'Adverbio que significa ''setenta veces'', indicando frecuencia o repetición. En Mateo 18:22, Jesús lo emplea al responder la pregunta de Pedro sobre el perdón: no solo siete veces, sino ''setenta veces siete'' (o ''setenta y siete veces'', según la interpretación). Cualquiera de las dos lecturas implica un perdón ilimitado. El número hace eco de Génesis 4:24, donde Lamec se jacta de venganza multiplicada; Jesús transforma la venganza en perdón. La cifra hiperbólica no busca un conteo literal, sino que expresa una gracia inagotable y sin límites.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1442', 'spa', 'Séptimo; número ordinal que designa la posición después de la sexta en una secuencia.', 'Adjetivo ordinal que significa ''séptimo'', derivado de ἑπτά (siete). Aparece en narraciones y visiones proféticas donde la séptima posición tiene un peso especial: la hora séptima cuando el hijo del noble es sanado (Jn 4:52), el séptimo día del reposo de la creación citado en Hebreos 4:4, Enoc como el séptimo desde Adán (Judas 1:14), y la dramática apertura del séptimo sello que trae silencio en el cielo (Ap 8:1). En todos estos contextos, la posición ordinal séptima conlleva una carga teológica que va más allá de la mera numeración, evocando plenitud y consumación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1443', 'spa', 'Éber, antepasado hebreo de Abraham, de cuyo nombre posiblemente deriva ''hebreo''; patriarca en la genealogía de Génesis', 'Éber (en hebreo עֵבֶר) fue descendiente de Sem y antepasado de Abraham, y aparece en las genealogías de Génesis 10-11 y Lucas 3:35. Su nombre puede ser el origen del término ''hebreo'' (ibri), designando al pueblo de Abraham como ''descendientes de Éber''. Vivió en la época de la Torre de Babel y la división de las lenguas. Lucas lo incluye en la genealogía de Jesús, trazando el linaje de Cristo a través de la línea patriarcal de Israel hasta Adán. El nombre significa ''el que viene del otro lado'' (del Éufrates).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1444', 'spa', 'Hebreo, relativo a la lengua hebrea o al pueblo judío y su cultura', 'Adjetivo que significa ''hebreo'', relativo a la lengua hebrea o a la cultura judía. En Lucas 23:38 (en algunos manuscritos), se describe la inscripción de Pilato sobre la cruz escrita en hebreo, griego y latín, las tres lenguas principales de la Judea del siglo primero. El hebreo (o el arameo, su dialecto emparentado) era la lengua étnica del pueblo judío, el griego la lengua internacional de comercio y el latín la lengua imperial romana. La inscripción trilingüe proclamaba la realeza de Jesús ante todos los grupos culturales presentes en Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1445', 'spa', 'Hebreo; designación étnico-religiosa de un israelita que conserva la lengua y costumbres ancestrales', 'En el Nuevo Testamento, este sustantivo identifica a alguien como israelita de habla hebrea (o aramea), distinguiéndolo frecuentemente de los judíos helenistas (grecófonos). La triple reivindicación de Pablo en Filipenses 3:5 —''hebreo de hebreos''— subraya pureza cultural y lingüística, no solo ascendencia. El término aparece en Hechos 6:1 precisamente en la línea de fractura entre creyentes judíos de habla aramea y de habla griega, revelando las tensiones de la iglesia primitiva. En 2 Corintios 11:22 Pablo vuelve a invocarlo para afirmar su pedigrí judío ante sus adversarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1446', 'spa', 'hebreo (lengua o dialecto); específicamente el arameo vernáculo hablado en la Judea del siglo I', 'El adjetivo Ἑβραΐς (forma femenina de Ἑβραϊκός) designa la lengua hebrea o, más precisamente en los contextos neotestamentarios, el dialecto arameo hablado en Palestina durante el siglo I. Cuando Hechos registra que Pablo habla ''en lengua hebrea'', se refiere al arameo, la lengua común de los judíos en Judea, a diferencia del griego. Esta elección lingüística tenía un profundo significado social y religioso: identificaba al hablante como auténticamente judío y se dirigía a los oyentes en su lengua del corazón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1447', 'spa', 'En hebreo (o arameo); designa el idioma en que se pronuncia una palabra o frase.', 'Adverbio que significa ''en lengua hebrea'', usado por Juan para senalar terminos semiticos a su audiencia grecohablante. Cada aparicion introduce un nombre de lugar o titulo que Juan luego traduce: Betesda (Jn 5:2), Gabata (19:13), Golgota (19:17) y Raboni (20:16). En Juan 19:20 aparece junto a ''en latin'' y ''en griego'' para describir la inscripcion trilingue de Pilato en la cruz. El termino probablemente abarca tanto el hebreo propiamente dicho como el arameo, ya que varias de las palabras glosadas son de forma aramea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1448', 'spa', 'Acercarse, aproximarse: espacialmente a una persona o lugar; temporalmente de eventos inminentes; espiritualmente a Dios.', 'Acercarse, aproximarse: espacialmente a una persona o lugar; temporalmente de eventos inminentes; espiritualmente a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1449', 'spa', 'Escribir en, inscribir, grabar; registrar permanentemente, especialmente en registros metafóricos de pertenencia', 'El verbo compuesto ἐγγράφω (ἐν + γράφω) significa escribir o inscribir en algo, grabar de manera permanente en un registro, una superficie o, metafóricamente, en los corazones. En el uso bíblico se subraya la permanencia del registro: nombres inscritos en los libros celestiales, leyes grabadas en el corazón. El acto de inscribir o registrar crea un testimonio duradero y con autoridad; lo que ha sido ἐγγεγραμμένον queda oficialmente asentado y permanece inscrito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1450', 'spa', 'Garante, fiador; persona que se compromete como aval para asegurar el cumplimiento de una obligación ajena', 'Este sustantivo designa a un garante, fiador o avalista: alguien que se compromete personalmente a asegurar que la obligación de otro será cumplida. Hebreos 7:22 declara a Jesús como el «garante de un pacto superior», lo cual significa que Él mismo asegura con su persona que todas las promesas del pacto se cumplirán. En el griego clásico se usaba para quien ofrecía garantía financiera o fianza. A diferencia del antiguo pacto, que dependía de la fidelidad humana y fracasó, el nuevo pacto descansa sobre la garantía perfecta de Jesús: su propia persona y obra respaldan lo que promete. Él es tanto el que promete como el que cumple.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1451', 'spa', 'Cerca, próximo; indica proximidad espacial o inminencia temporal, a menudo con matices escatológicos.', 'Cerca, próximo; indica proximidad espacial o inminencia temporal, a menudo con matices escatológicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1452', 'spa', 'Más cerca, más próximo en espacio o tiempo; forma comparativa que indica distancia reducida', 'Adverbio comparativo que significa «más cerca» o «más próximo», indicando cercanía en espacio o tiempo. Romanos 13:11 lo emplea en sentido temporal: «nuestra salvación está ahora más cerca que cuando creímos por primera vez». Pablo subraya el avance progresivo de la historia redentora: cada día acerca más a los creyentes al retorno de Cristo y a la consumación de la salvación. La forma comparativa enfatiza el movimiento hacia una meta. El tiempo no es cíclico sino lineal, avanzando hacia el día en que la fe se convertirá en vista y la esperanza en realidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1453', 'spa', 'Levantar, despertar, resucitar; especialmente de la resurrección de entre los muertos; también levantarse físicamente o despertar del sueño', 'Uno de los verbos con mayor carga teológica del Nuevo Testamento, que abarca desde el simple despertar hasta la resurrección escatológica. En su sentido más cotidiano significa ''levantarse'' o ''despertar del sueño'', pero su uso definitorio en el NT es la resurrección de Jesús de entre los muertos: ἠγέρθη, ''ha resucitado'' (Mt 28:6). La voz pasiva en contextos de resurrección conlleva un peso teológico enorme: el sujeto no se resucita a sí mismo, sino que es resucitado por el poder divino. El mismo verbo cubre también el levantarse físico, la aparición profética y el alzamiento de naciones, una amplitud semántica notable unificada por la imagen central de pasar de un estado inferior a uno superior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1454', 'spa', 'Resurrección, levantamiento; acto de despertar o levantar del sueño o de la muerte', 'Este sustantivo significa levantamiento, despertar o resurrección: el acto de hacer que alguien se levante del sueño o de la muerte. Mateo 27:53 lo utiliza para la resurrección de santos que salieron de sus tumbas «después de la resurrección de Él» y se aparecieron a muchos. El término puede referirse al simple despertar del sueño o, de forma más trascendente, a la resurrección de entre los muertos. Deriva del verbo «levantar» o «despertar». La referencia de Mateo vincula la resurrección de Jesús con la de creyentes del Antiguo Testamento, mostrando su muerte y resurrección como el eje de toda esperanza de resurrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1455', 'spa', 'Espías, agentes secretos infiltrados para obtener información o tender una trampa', 'Este adjetivo usado como sustantivo significa espías o agentes secretos: personas infiltradas para obtener información o crear una trampa. Lucas 20:20 describe cómo los líderes religiosos enviaron «espías que fingían ser justos» para atrapar a Jesús con sus propias palabras y poder entregarlo a las autoridades romanas. El término enfatiza su naturaleza encubierta y engañosa: fingían sinceridad mientras en realidad buscaban tenderle una trampa. En el griego clásico se usaba para personas insertadas secretamente en situaciones con fines de vigilancia o subversión. Estos agentes intentaron forzar a Jesús a hacer declaraciones políticamente peligrosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1456', 'spa', 'Fiesta de la Dedicación, festividad judía que conmemora la rededicación del templo por Judas Macabeo en 164 a.C.', 'La Fiesta de la Dedicación (Januká), festividad judía de ocho días que conmemora la rededicación del templo en 164 a.C. después de que Antíoco Epífanes lo profanara. Judas Macabeo purificó y rededicó el templo tras la revuelta macabea. Juan 10:22 señala que Jesús se encontraba en Jerusalén durante esta fiesta, caminando por el pórtico de Salomón en invierno. Aunque no fue ordenada en la Torá, esta fiesta celebraba la fidelidad de Dios al restaurar el culto del templo. La presencia de Jesús allí y sus declaraciones acerca de ser el verdadero templo adquieren un significado especial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1457', 'spa', 'inaugurar, dedicar, consagrar para primer uso', 'Este verbo significa inaugurar o dedicar algo para su primer uso sagrado. En Hebreos 9:18 y 10:20, describe la consagración del antiguo pacto y el nuevo camino abierto mediante el sacrificio de Cristo. El término conlleva connotaciones de dedicación ritual, haciendo que algo sea recién operativo para su propósito santo. Ambos usos en Hebreos conectan el sacrificio con la inauguración de la relación de pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1458', 'spa', 'Presentar cargos formales o una acusación legal contra alguien; acusar en un contexto judicial.', 'Término técnico del ámbito jurídico griego que designa la acción de presentar una acusación formal contra una persona ante un tribunal. En el Nuevo Testamento aparece exclusivamente en Lucas-Hechos y Romanos, siempre en contextos de procedimientos judiciales: ante magistrados romanos (Hch 19:38, 19:40), el Sanedrín (Hch 23:28–29) o el tribunal imperial (Hch 26:2). Pablo también lo emplea teológicamente en Romanos 8:33, preguntando quién presentará cargos contra los elegidos de Dios. La evidencia multilingüe confirma este enfoque forense: el español ''acusar'', el francés ''accuser'' y el alemán ''anklagen'' apuntan inequívocamente a la acusación formal, no a la culpa casual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1459', 'spa', 'Abandonar, desamparar, dejar — ya sea desertar a una persona en necesidad o descuidar la reunión comunitaria. ἐγκαταλείπω (egkataleipo) es uno de los ', 'Abandonar, desamparar, dejar — ya sea desertar a una persona en necesidad o descuidar la reunión comunitaria. ἐγκαταλείπω (egkataleipo) es uno de los verbos con mayor carga emocional del Nuevo Testamento. Jesús clama desde la cruz: ''Dios mío, Dios mío, ¿por qué me has desamparado?'' (Mateo 27:46; Marcos 15:34), citando el Salmo 22:1, y sin embargo Pedro en Pentecostés declara que Dios no ''abandonó'' a su Santo en el sepulcro (Hechos 2:27, 31). Pablo lo emplea para referirse a la deserción personal: ''Demas me ha abandonado'' (2 Timoteo 4:10) y ''todos me desampararon'' (2 Timoteo 4:16). La palabra también se extiende al descuido de la congregación (Hebreos 10:25), donde el objeto pasa de una persona a una práctica comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1460', 'spa', 'Habitar entre, residir en medio de; vivir dentro de o junto a una comunidad', 'Participio que significa ''habitar entre'' o ''vivir en medio de'' un grupo de personas, residiendo dentro de una comunidad. En 2 Pedro 2:8 se describe al justo Lot ''habitando entre'' los habitantes de Sodoma, cuyos actos inicuos atormentaban diariamente su alma justa. El término subraya la proximidad física y la residencia continua. En el griego clásico se empleaba para referirse a habitar un lugar o vivir entre un pueblo. El argumento de Pedro es que la ubicación geográfica de Lot no lo corrompió: mantuvo su justicia a pesar de la exposición constante a la maldad, demostrando que Dios puede preservar al piadoso incluso en ambientes impíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1461', 'spa', 'Injertar una rama en un árbol; usado metafóricamente para incorporar creyentes al pueblo del pacto de Dios.', 'Tomado del mundo agrícola del cultivo del olivo, este verbo significa insertar un brote o vástago en un patrón para que pueda recibir vida del árbol anfitrión. Pablo se apropia de la imagen en Romanos 11:17-24, donde las ramas de olivo silvestre (los creyentes gentiles) son injertadas en el olivo cultivado (Israel). El español ''injertar'' y el francés ''greffer'' conservan la precisión hortícola, mientras que la metáfora porta una carga teológica profunda: la vida fluye desde la raíz hacia cada rama injertada por igual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1462', 'spa', 'cargo, acusación, denuncia formal', 'Este término legal denota una acusación formal o cargo presentado contra alguien. En Hechos 23:29 y 25:16, aparece en los procedimientos legales romanos contra Pablo, refiriéndose a los cargos específicos presentados por sus acusadores. La palabra pertenece al vocabulario técnico de la jurisprudencia grecorromana, indicando denuncias escritas que podían conducir a juicio. Ambas ocurrencias enfatizan la naturaleza oficial y legal de la acusación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1463', 'spa', 'Revestirse de, ponerse como vestidura; envolverse en algo o llevarlo puesto', 'Verbo en voz media que significa revestirse de algo o ponerse una prenda. En 1 Pedro 5:5 se exhorta a los creyentes a ''revestirse de humildad unos para con otros'', utilizando la imagen de ponerse una vestidura o delantal. En el griego clásico se usaba para atarse algo encima o llevarlo puesto constantemente. La metáfora de Pedro sugiere que la humildad debe ser tan visible y constante como la ropa que uno lleva, no una actitud ocasional sino una disposición permanente que los creyentes asumen deliberadamente en todas sus relaciones. La humildad se convierte así en el ''uniforme'' de la comunidad cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1464', 'spa', 'Estorbo, obstáculo, impedimento; algo que bloquea el avance o genera dificultad', 'Sustantivo que significa estorbo, obstáculo o impedimento: algo que bloquea el progreso o crea dificultad. Pablo lo emplea en 1 Corintios 9:12 al explicar por qué rechaza el sustento económico: ''para no poner ningún obstáculo al evangelio de Cristo''. El término puede referirse tanto a barreras físicas como a impedimentos figurados. En el griego clásico se usaba para incisiones, interrupciones u obstáculos materiales. La preocupación de Pablo es pastoral: está dispuesto a renunciar a derechos legítimos antes que crear cualquier estorbo que pueda frenar el avance del evangelio. Nada debe interponerse entre las personas y el mensaje de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1465', 'spa', 'Estorbar, impedir o interponerse; obstruir el progreso o los planes de alguien', 'Originalmente con el sentido de «cortar en» (de ἐν + κόπτω), este verbo pasó a significar obstruir o impedir el curso de acción de alguien. Pablo lo usa repetidamente para explicar por qué sus planes fueron frustrados: fue «impedido» de visitar Roma (Romanos 15:22) y Tesalónica (1 Tesalonicenses 2:18). En Gálatas 5:7 evoca una metáfora atlética —«¿quién os estorbó para no obedecer a la verdad?»— como si alguien se hubiera interpuesto durante una carrera. Pedro exhorta a los esposos a honrar a sus esposas para que sus oraciones no sean «estorbadas» (1 Pedro 3:7). Las traducciones en español «estorbar/impedir» y en alemán «hindern» confirman el sentido de obstrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1466', 'spa', 'Dominio propio; gobierno sobre los propios deseos, apetitos e impulsos', 'Virtud que denota la fortaleza interior para gobernar las propias pasiones y apetitos. En Gálatas 5:23 corona la lista del fruto del Espíritu, mientras que en 2 Pedro 1:6 aparece dos veces en una cadena que enlaza el conocimiento con la piedad. Cuando Pablo razonó sobre ''la justicia, el dominio propio y el juicio venidero'' ante Félix (Hch 24:25), el gobernador tembló, lo que sugiere que no se trataba de un ideal abstracto sino de una exigencia moral penetrante. La dimensión reflexiva del término —autoridad ejercida sobre uno mismo— queda bien reflejada en la expresión española ''dominio propio''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1467', 'spa', 'ejercer autocontrol, practicar dominio propio', 'Este verbo en voz media significa ejercer autocontrol o disciplinarse a sí mismo. Pablo lo usa en 1 Corintios 7:9 respecto al autocontrol sexual en contextos matrimoniales, y en 9:25 sobre la disciplina del entrenamiento atlético. El término enfatiza el autodominio activo más que la mera restricción pasiva. El griego antiguo también lo usaba para forzarse a hacer algo difícil, destacando la naturaleza intencional y esforzada de la autodisciplina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1468', 'spa', 'Con dominio propio, disciplinado, que ejerce control sobre sus deseos e impulsos; temperante', 'Adjetivo que significa disciplinado o con dominio propio: quien ejerce control sobre sus deseos, impulsos y apetitos. En Tito 1:8 se enumera entre los requisitos para los ancianos: deben ser dueños de sí mismos, justos, santos y disciplinados. En el griego clásico se aplicaba a quienes tenían poder sobre sí mismos, señores de sus pasiones. El término enfatiza una fortaleza de carácter que refrena los impulsos destructivos. Los líderes deben modelar la autodisciplina que exigen a otros, controlando la lengua, el temperamento, los apetitos y las ambiciones mediante el poder del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1469', 'spa', 'Contar entre, clasificar con; considerar a alguien como perteneciente a un grupo o categoría determinada', 'Verbo que describe el acto de situar a alguien dentro de una categoría particular o considerarlo parte de un grupo específico. En 2 Corintios 10:12, Pablo lo emplea para referirse a quienes se atreven a clasificarse a sí mismos entre los dignos de elogio, con un matiz de autoevaluación y comparación. La evidencia multilingüe (español ''incluirnos'', francés ''compter parmi'', alemán ''sich vergleichen'') capta tanto el sentido de contarse entre un grupo como la dimensión comparativa de esta acción clasificatoria. El uso clásico confirma el significado de ''contar dentro de'' o ''incluir entre''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1470', 'spa', 'Esconder, ocultar dentro; colocar algo dentro de otra cosa de modo que quede oculto a la vista', 'Este verbo compuesto describe la accion de esconder algo colocandolo dentro de otra cosa, ocultandolo en su interior. En Mateo 13:33, Jesus lo emplea en la parabola donde una mujer esconde levadura en tres medidas de harina, una imagen vivida de la obra oculta y transformadora del reino. Las traducciones multilingues (espanol ''escondio'', frances ''cacher'', ingles ''hid'') enfatizan de manera consistente el aspecto de ocultamiento, aunque el aleman preserva la forma griega misma, reconociendo quiza la precision tecnica de esta composicion verbal particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1471', 'spa', 'Embarazada, encinta; que describe a una mujer que lleva un hijo en su vientre', 'Este adjetivo describe el estado de embarazo, literalmente ''que tiene dentro'' (de la raiz que significa ''concebir''). Lucas lo usa en 2:5 para describir a Maria viajando a Belen mientras estaba encinta de Jesus. La evidencia multilingue muestra una notable consistencia (ingles ''pregnant'', espanol ''encinta'', frances ''enceinte''), todas transmitiendo este estado fisiologico. Las fuentes clasicas confirman que se aplicaba tanto a humanos como a animales, e incluso metaforicamente al caballo de Troya como ''prenado de silencio'', mostrando el rango semantico del termino desde la contencion literal hasta la figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1472', 'spa', 'Ungir, frotar con aceite o ungueento; aplicar una sustancia sobre la superficie, especialmente con fines medicinales o rituales', 'Este verbo significa ungir o frotar con aceite o ungueento. En Apocalipsis 3:18, Jesus aconseja a la iglesia de Laodicea ungir sus ojos con colirio para que puedan ver, una metafora de la percepcion espiritual. La evidencia multilingue refleja tanto la uncion religiosa (ingles ''to anoint'', espanol ''ungir'') como la aplicacion medicinal (frances y aleman ''einreiben'' = frotar). El uso clasico confirma ambas dimensiones: la uncion ritual y la aplicacion farmaceutica, extendiendose incluso al sentido de ''escozor'' producido por sustancias frotadas sobre la piel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1473', 'spa', 'Yo, me; el pronombre de primera persona singular en todas sus formas de caso', 'Yo, me — el pronombre de primera persona singular en todas sus declinaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1474', 'spa', 'Derribar hasta el suelo, arrasar; demoler arrojando por tierra, sin dejar nada en pie', 'Este verbo vivido significa arrasar algo por completo, derribarlo contra el suelo hasta dejarlo llano como un pavimento. En Lucas 19:44, Jesus profetiza que los enemigos ''te derribaran a ti y a tus hijos'' dentro de Jerusalen, una imagen devastadora de destruccion total. La palabra originalmente significaba ''aplanar como un piso'' (de ''edaphos'' = suelo/pavimento), transmitiendo una demolicion sistematica y exhaustiva. La evidencia multilingue (espanol ''derribaran'' = demoler, frances ''raser'' = arrasar) confirma este sentido de nivelacion completa, no mero dano sino destruccion absoluta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1475', 'spa', 'Suelo, piso, pavimento; la superficie inferior o base, ya sea tierra al aire libre o piso en interiores', 'Este sustantivo designa el suelo, el piso o cualquier superficie inferior, desde fondos de barcos y lechos de rios hasta pisos de casas y pavimentos de ciudades. En Hechos 22:7, Pablo describe haber caido ''al suelo'' durante su encuentro en el camino a Damasco. El uso clasico muestra una amplia aplicacion: cimientos, pavimentos, plantas bajas, incluso el suelo de la patria. La evidencia multilingue es consistente (ingles ''ground'', espanol ''suelo'', frances ''sol''), apuntando todas a la superficie fundamental sobre la cual las cosas descansan o hacia la cual caen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1476', 'spa', 'Firme, constante, asentado; que describe estabilidad inquebrantable en posición, propósito o convicción', 'El adjetivo ἑδραῖος (de ἕδρα, «asiento») significaba originalmente «sentado» o «sedentario», pero evolucionó hacia firmemente establecido, inamovible, constante. En el Nuevo Testamento describe la estabilidad que Pablo insta a los creyentes: propósito resuelto, determinación inquebrantable, compromiso inamovible con la fe y el servicio. La palabra sugiere una firmeza profundamente arraigada, no mera terquedad, como un edificio sobre cimiento sólido o una persona plantada en su lugar, inmutable ante los vientos cambiantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1477', 'spa', 'Fundamento, soporte, baluarte; aquello que proporciona estabilidad y firmeza a algo', 'Este sustantivo significa fundamento o soporte, aquello que estabiliza y sostiene. En 1 Timoteo 3:15, Pablo llama a la iglesia «columna y fundamento de la verdad», una impactante metáfora arquitectónica que describe el papel de la iglesia en la preservación de la verdad revelada. La palabra aparece únicamente en este pasaje del Nuevo Testamento, denotando un soporte firme o baluarte. La evidencia multilingüe (inglés ''foundation'', español ''fundamento'', alemán ''Grundfeste'' = base firme) coincide en el sentido de apoyo arquitectónico, mientras que el francés simplemente transliterael griego, reconociendo su carácter técnico o infrecuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1478', 'spa', 'Ezequías, rey de Judá conocido por reformas y fe', 'La forma griega del nombre hebreo que significa ''fuerza de Yahveh'', refiriéndose al rey reformador de Judá (715-686 a.C.). Ezequías es recordado por sus reformas religiosas, su confianza en Dios durante la invasión asiria, y la extensión milagrosa de su vida. Mateo 1:9-10 lo incluye en la genealogía de Jesús, apareciendo dos veces como padre e hijo en generaciones sucesivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1479', 'spa', 'Religión autoimpuesta, culto voluntario; prácticas religiosas elegidas por voluntad humana y no por mandato divino', 'Este sustantivo compuesto, que aparece exclusivamente en Colosenses 2:23, describe un «culto voluntario» o religiosidad autoimpuesta: prácticas inventadas por preferencia humana en lugar de ordenadas por Dios. Se trata de una crítica a la espiritualidad autoproclamada que parece devota pero carece de autorización divina. La evidencia multilingüe revela el concepto: el inglés ''self-made religion'', el español ''culto voluntario'', en contraste con la adoración prescrita por las Escrituras. Es la advertencia de Pablo contra prácticas ascéticas de apariencia impresionante pero de origen puramente humano, sin verdadero mandato divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1480', 'spa', 'Acostumbrado, habitual, conforme a la costumbre; lo que se realiza regularmente como práctica establecida', 'Este participio perfecto pasivo funciona como adjetivo con el significado de «acostumbrado» o «conforme a la costumbre establecida». En Lucas 2:27, describe a José y María cumpliendo con Jesús «conforme a la costumbre de la Ley», es decir, siguiendo la práctica establecida. La palabra proviene de un verbo que significa «acostumbrar», y en su forma pasiva perfecta indica algo que se ha vuelto habitual o consuetudinario. La evidencia multilingüe (español ''acostumbrado'', francés ''habituel'') confirma el sentido de práctica establecida, aquello que se ha convertido en norma mediante la repetición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1481', 'spa', 'Etnarca, gobernante de un pueblo; gobernador o líder de un grupo étnico o provincia', 'Este título designa a un «etnarca» o gobernante de un pueblo, un líder político que administraba un grupo étnico o un territorio provincial. En 2 Corintios 11:32, Pablo menciona «al etnarca del rey Aretas» que vigilaba Damasco para arrestarlo. Históricamente, los etnarcas gobernaban territorios o grupos étnicos con una autoridad inferior a la de los reyes pero superior a la de los funcionarios locales. La evidencia multilingüe generalmente transliterael título técnico (español ''etnarca'', francés ''ethnarque''), mientras que el alemán ''Statthalter'' (gobernador) ofrece una equivalencia funcional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1482', 'spa', 'Gentil; persona pagana o no judía, alguien perteneciente a las naciones fuera del pacto de Israel', 'Este adjetivo sustantivado designa a quien pertenece a las naciones (ἔθνη) y no a Israel. Jesús lo emplea en el Sermón del Monte para describir conductas que sus seguidores deben superar: hasta los gentiles saludan a los suyos (Mt 5:47) y acumulan palabras vacías al orar (Mt 6:7). En Mateo 18:17 se convierte en la categoría más extrema de distancia social: ''tenlo por gentil y publicano''. En 3 Juan 1:7 el término señala a los paganos de quienes los misioneros itinerantes no aceptan ayuda, subrayando la frontera entre la comunidad creyente y quienes permanecen fuera del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1483', 'spa', 'A la manera gentil, como las naciones; comportarse según costumbres no judías en lugar de la ley judía', 'Este adverbio significa «a la manera gentil» o «como las naciones», es decir, comportarse según costumbres no judías en lugar de la observancia de la Torá. En Gálatas 2:14, Pablo confronta a Pedro por obligar a los gentiles «a vivir como judíos» cuando él mismo a veces vivía «como gentil» (el contraste implícito). La palabra deriva de «ἐθνικός» (nacional, gentil), y la forma adverbial describe una conducta característica de los no judíos. La evidencia multilingüe (español ''gentílicamente'', alemán ''heidnisch'' = a la manera pagana) refleja esta distinción étnico-cultural entre el estilo de vida judío y el gentil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1484', 'spa', 'Nación, pueblo, grupo étnico; en el NT frecuentemente ''los gentiles'' — pueblos no judíos en contraste colectivo con Israel', 'Uno de los sustantivos con mayor carga teológica del Nuevo Testamento. En su sentido más amplio simplemente significa ''nación'' o ''pueblo'' — cualquier grupo étnico o político, incluido el propio Israel (Mt 21:43, ''una nación que produzca sus frutos''). Pero en el uso paulino y de la iglesia primitiva, el plural τὰ ἔθνη se convirtió en término casi técnico para ''los gentiles'', aquellos fuera del pacto de Israel. ''Naciones'' conserva el sentido neutral, mientras que ''gentiles'' señala el significado teológico especializado. Romanos 1-2 muestra ambos: el evangelio va a las naciones (1:5), y los gentiles que por naturaleza cumplen la ley revelan la universalidad de la norma divina (2:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1485', 'spa', 'Costumbre, hábito — una práctica establecida o tradición, especialmente en la vida religiosa o comunitaria. ἔθος denota un patrón de comportamiento as', 'Costumbre, hábito — una práctica establecida o tradición, especialmente en la vida religiosa o comunitaria. ἔθος denota un patrón de comportamiento asentado que ha adquirido la fuerza de tradición o convención. En el Nuevo Testamento sus 12 apariciones se agrupan en torno a la observancia religiosa y la costumbre legal — el sorteo sacerdotal en Lucas 1:9, la peregrinación pascual en Lucas 2:42, la práctica funeraria judía en Juan 19:40, y las costumbres discutidas de Moisés en Hechos 6:14 y 15:1. La palabra no conlleva juicio inherente sobre si una costumbre es buena o mala; el contexto aporta esa evaluación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1486', 'spa', 'Acostumbrar, soler; seguir un hábito o costumbre establecida', 'Proveniente de la raíz griega para hábito, este verbo aparece casi exclusivamente en su forma perfecta (εἴωθα), que funciona como un presente: ''es costumbre'' o ''solía''. El Nuevo Testamento lo usa para describir prácticas arraigadas: la costumbre de Pilato de liberar a un preso en la Pascua (Mt 27:15), la asistencia habitual de Jesús a la sinagoga en sábado (Lc 4:16) y el patrón regular de Pablo de razonar a partir de las Escrituras (Hch 17:2). Transmite la idea de una regularidad profundamente incorporada en la conducta, no un acto aislado sino una práctica consolidada por repetición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1487', 'spa', 'Si — partícula condicional primaria del griego; también en la combinación εἰ μή (si no, excepto, a menos que)', 'Como partícula condicional estándar del griego neotestamentario, εἰ introduce la prótasis (cláusula ''si'') de oraciones condicionales de todo tipo: condiciones reales (εἰ + indicativo), contrarias a la realidad y formas mixtas. Aparece más de 500 veces, lo que la convierte en una de las palabras funcionales más frecuentes del NT. Un patrón secundario importante es la combinación εἰ μή (''si no''), que funciona como marcador exceptivo con el significado de ''excepto'' o ''a menos que'', como en Mt 11:27: ''nadie conoce al Padre sino (εἰ μή) el Hijo''. El español distingue claramente ambos usos: ''si'' para el condicional y ''sino'' para el exceptivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1488', 'spa', 'ser, existir; el verbo de existencia en sus formas subjuntivas y optativas', 'El verbo griego «ser» (εἰμί) en sus diversas formas conjugadas que expresan existencia, identidad o predicación. Este verbo sumamente irregular aparece en numerosas variantes dialectales a lo largo de la literatura griega. Como la cópula más fundamental, vincula sujetos con predicados, afirma la existencia o indica ubicación y estado. El verbo constituye la columna vertebral de la predicación griega, permitiendo enunciar qué es algo, dónde se encuentra, qué características posee o simplemente que existe. El griego bíblico lo emplea constantemente en declaraciones existenciales, en la identificación de Jesús como Mesías y en predicaciones teológicas sobre la naturaleza de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1489', 'spa', 'partícula enfática: al menos, por lo menos, en verdad; a menudo solo se expresa con énfasis vocal', 'Partícula enclítica que añade énfasis a la palabra o palabras que la preceden. Con frecuencia solo puede captarse en la escritura mediante cursivas o en el habla mediante el acento prosódico, ya que no siempre se traduce con un vocablo específico. Según el contexto, puede significar «al menos», «por lo menos», «en verdad» o «por mi parte». Con pronombres subraya la implicación personal o la distinción («yo al menos», «tú por tu parte»). En contextos negativos intensifica la negación («ni siquiera», «ni lo más mínimo»). La partícula aparece con mayor frecuencia en la prosa ática que en Homero, y su forma dórica es γα. Sirve principalmente para resaltar o enfatizar elementos específicos dentro de la oración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1490', 'spa', 'De otra manera, si no, de lo contrario; partícula condicional que introduce un escenario alternativo o consecuencia contraria.', 'Partícula condicional compacta que significa ''de otra manera'' o ''si no'', utilizada para señalar lo que ocurriría bajo una condición alternativa. Jesús advierte que practicar la justicia para aprobación humana significa que ''de otra manera no tendréis recompensa'' (Mt 6:1), y explica que el vino nuevo en odres viejos los reventará — ''de lo contrario'' el vino se pierde (Mt 9:17; Lc 5:36-37). Pablo la emplea en argumentación teológica: ''de otra manera la gracia ya no sería gracia'' (Ro 11:6). La palabra posee una agudeza lógica, marcando la frontera entre una condición y su contraria, funcionando como bisagra argumentativa en la enseñanza de Jesús y en la teología paulina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1491', 'spa', 'Forma, apariencia, aspecto visible; la figura externa o tipo de algo percibido por los sentidos', 'Se refiere a la forma o apariencia visible de algo tal como se percibe exteriormente. En el bautismo de Jess, el Espritu desciende en ''forma'' corporal como paloma (Lucas 3:22), y durante la Transfiguracin la ''apariencia'' de su rostro se transforma (Lucas 9:29). Jess les dice a las multitudes que nunca han visto la ''forma'' del Padre (Juan 5:37). Pablo contrasta el caminar ''por fe, no por vista'', es decir, no por la apariencia visible (2 Corintios 5:7). En 1 Tesalonicenses 5:22, los creyentes deben abstenerse de toda ''forma'' o especie de mal. El trmino abarca tanto la figura concreta como la categora o clase de algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1492', 'spa', 'Saber, conocer; del perfecto de εἶδον (''ver''), que significa saber hechos o verdades, o conocer personalmente por experiencia', 'Enraizado en la conexión antigua entre ver y saber (compárese el latín videre, el sánscrito veda), οἶδα en su tiempo perfecto llegó a significar ''sé'' — un conocimiento ya adquirido y establecido. En la mayoría de sus 321 apariciones neotestamentarias denota conocimiento factual o proposicional: ''sabéis que dentro de dos días se celebra la Pascua'' (Mt 26:2). El español refleja con nitidez la distinción: ''saber'' para el conocimiento factual frente a ''conocer'' para el trato personal, correspondiendo exactamente a los dos sentidos. El sentido menor de conocimiento personal aparece cuando alguien reconoce a una persona o situación de primera mano (Mt 27:18; Lc 6:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1493', 'spa', 'Templo de ídolos, santuario pagano; edificio o espacio sagrado dedicado al culto de imágenes e ídolos', 'Este sustantivo designa un templo dedicado al culto idolátrico. En 1 Corintios 8:10, Pablo aborda la problemática de que un cristiano sea visto «reclinado en un templo de ídolos», es decir, participando en comidas dentro de recintos sagrados paganos vinculados al culto templario. El término compuesto combina «ídolo» (εἴδωλον) con un sufijo locativo, creando una palabra específica para edificios que albergan culto a ídolos. La evidencia multilingüe es notablemente consistente: español «templo de ídolos», francés «temple d''idole», alemán «Götzentempel», todas transmitiendo la arquitectura religiosa dedicada al culto pagano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1494', 'spa', 'Alimento sacrificado a ídolos, carne ofrecida a ídolos — un tema central en el debate ético del cristianismo primitivo. Sustantivo compuesto que desig', 'Alimento sacrificado a ídolos, carne ofrecida a ídolos — un tema central en el debate ético del cristianismo primitivo. Sustantivo compuesto que designa carne o alimento que ha sido ofrecido ritualmente a una deidad pagana antes de venderse en el mercado o consumirse en banquetes del templo. El término se sitúa en el centro de dos debates distintos del cristianismo primitivo: el decreto apostólico de Hechos 15:29 (reiterado en 21:25) lo prohíbe junto con la sangre y la inmoralidad sexual, mientras que el extenso tratamiento de Pablo en 1 Corintios 8-10 matiza el asunto en torno al conocimiento, la conciencia y el amor hacia los creyentes más débiles. Apocalipsis 2:14, 20 condena a las iglesias que toleran su consumo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1495', 'spa', 'Idolatría; adoración de ídolos o dioses falsos, extendida a toda devoción suprema mal dirigida', 'Sustantivo compuesto (εἴδωλον + λατρεία) que denota el servicio rendido a imágenes o dioses falsos. Pablo lo emplea tanto en sentido literal como metafórico: en 1 Corintios 10:14 insta a los creyentes a ''huir de la idolatría'' en el contexto de los banquetes en templos paganos, mientras que en Colosenses 3:5 equipara llamativamente la avaricia con la idolatría. Gálatas 5:20 la incluye entre las ''obras de la carne'', y 1 Pedro 4:3 la recuerda como parte del pasado pagano de los conversos. El término abarca desde el culto literal a imágenes hasta la entrega del corazón a cualquier cosa que desplace a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1496', 'spa', 'Idólatra; quien adora imágenes o dioses falsos, extendido también a la infidelidad espiritual como la avaricia.', 'Sustantivo compuesto formado por εἴδωλον (''imagen, ídolo'') y λάτρης (''adorador''), que designa a quien rinde culto a dioses falsos o a sus imágenes. Pablo lo emplea en listas de vicios junto a inmorales sexuales, borrachos y avaros (1 Co 5:10–11; 6:9), y de manera llamativa equipara la codicia con la idolatría en Efesios 5:5. Apocalipsis cierra el canon con esta palabra en labios del juicio, excluyendo a los idólatras de la ciudad santa (Ap 21:8; 22:15). Aunque el sentido concreto apunta a la adoración de imágenes, el uso paulino extiende el término a cualquier lealtad suprema que desplace a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1497', 'spa', 'Ídolo, imagen de un dios falso — una representación física de una deidad usada en la adoración pagana. El sustantivo εἴδωλον (eidolon) designa una ima', 'Ídolo, imagen de un dios falso — una representación física de una deidad usada en la adoración pagana. El sustantivo εἴδωλον (eidolon) designa una imagen física de una deidad adorada en lugar del Dios verdadero, con un juicio teológico inherente de que estas son meras formas. Esteban relata cómo Israel fabricó un becerro como ídolo en el desierto (Hechos 7:41). El concilio de Jerusalén advierte contra las ''contaminaciones de los ídolos'' (Hechos 15:20). Pablo argumenta que ''un ídolo nada es en el mundo'', pero reconoce el peligro moral para las conciencias débiles (1 Corintios 8:4, 7; 10:19). Juan advierte: ''guardaos de los ídolos'' (1 Juan 5:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1498', 'spa', 'ser, estar, existir; formas optativas del verbo de existencia', 'El verbo griego «ser» (εἰμί) en sus diversas formas conjugadas, que expresan existencia, identidad o predicación. Este verbo altamente irregular aparece en numerosas variantes dialectales a lo largo de la literatura griega. Como la cópula más fundamental, vincula sujetos con predicados, afirma la existencia o indica ubicación y estado. Funciona como la columna vertebral de la predicación griega, permitiendo enunciar qué es algo, dónde se encuentra, qué características posee o simplemente que existe. El griego bíblico lo emplea constantemente para declaraciones existenciales, la identificación de Jesús como Mesías y predicaciones teológicas sobre la naturaleza de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1499', 'spa', 'si (condicional); si, acaso (pregunta indirecta); ¡ea! (interjección)', 'Una partícula versátil que cumple múltiples funciones gramaticales en griego. Con mayor frecuencia introduce cláusulas condicionales («si»), donde su negación habitual es μή. También introduce preguntas indirectas («si», «acaso»), caso en el cual su negación es οὐ. En Homero puede servir como interjección con imperativos («¡ea!», «¡vamos!») o introducir deseos con el modo optativo. Con el optativo expresa anhelos, a menudo irrealizados o irrealizables. Con tiempos pasados del indicativo puede expresar condiciones contrarias a la realidad o deseos no cumplidos. Esta partícula es fundamental para la sintaxis griega, pues habilita el razonamiento hipotético, las preguntas y la expresión del deseo o el pesar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1500', 'spa', 'En vano; sin propósito ni resultado; inútilmente.', 'Adverbio que señala que una acción ha sido fútil o carente de propósito. Pablo lo usa de manera incisiva en sus cartas para sacudir la complacencia: la fe recibida ''en vano'' si Cristo no ha resucitado (1 Co 15:2), el sufrimiento soportado ''en vano'' si los gálatas retornan a la ley (Gá 3:4), y el trabajo invertido ''en vano'' si vuelven a la observancia de calendarios (Gá 4:11). La palabra lleva un aguijón: implica un esfuerzo o experiencia real que ha quedado desprovisto de sentido. El español ''en vano'' y el francés ''en vain'' capturan esa misma resonancia de vacío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1501', 'spa', 'Veinte — el número cardinal veinte, εἴκοσι (eikosi), que aparece once veces en el NT en diversos contextos de conteo. Jesús lo emplea en la parábola d', 'Veinte — el número cardinal veinte, εἴκοσι (eikosi), que aparece once veces en el NT en diversos contextos de conteo. Jesús lo emplea en la parábola del rey que calcula si diez mil pueden enfrentar a veinte mil (Lc 14:31). Los discípulos reman unos veinticinco estadios cuando Jesús camina sobre el agua (Jn 6:19). Hechos registra ciento veinte creyentes en el aposento alto (Hch 1:15) y una sonda de veinte brazas (Hch 27:28). En Apocalipsis, los veinticuatro ancianos aparecen repetidamente alrededor del trono de Dios (Ap 4:4, 10; 5:8; 11:16; 19:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1502', 'spa', 'Ceder, someterse; rendirse o hacer concesiones ante la presión en lugar de resistir', 'Este verbo significa ceder, dar paso o someterse ante la presión. En Gálatas 2:5, Pablo insiste en que él y sus compañeros «ni por un momento cedimos en sumisión» ante los falsos hermanos que exigían la circuncisión. La palabra conlleva connotaciones de ceder terreno, hacer concesiones o doblegarse bajo presión. El uso clásico confirma este sentido de rendirse o dar paso. La evidencia multilingüe refleja consistentemente la idea de someterse o ceder terreno ante la oposición: español «cedimos», alemán «nachgeben» (dar paso).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1503', 'spa', 'ser semejante, asemejarse, parecer similar a', 'Este verbo en tiempo perfecto con significado presente expresa semejanza o parecido. Santiago lo usa dos veces en el capítulo 1 para crear comparaciones vívidas: el que duda es como una ola impulsada por el viento (v.6), y el oyente que olvida es como alguien que se mira en un espejo y se va (v.23). La palabra introduce símiles que hacen concretas y memorables las realidades espirituales abstractas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1504', 'spa', 'Imagen, semejanza, representación -- forma visible que refleja un original, ya sea retrato en moneda, ídolo o naturaleza divina.', 'Imagen, semejanza, representación -- forma visible que refleja un original, ya sea retrato en moneda, ídolo o naturaleza divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1505', 'spa', 'Sinceridad, pureza de motivos; autenticidad genuina sin pretensiones ni segundas intenciones', 'El sustantivo εἰλικρίνεια deriva de εἰλικρινής (posiblemente de ἡλή «luz solar» + κρίνω «juzgar», lo que resiste el escrutinio de la luz). Denota pureza, sinceridad, ausencia de mezcla o engaño, una integridad que no teme ser examinada. En el uso paulino describe tanto la celebración adecuada de las fiestas cristianas como el ministerio apostólico auténtico: una conducta lo suficientemente pura como para soportar el escrutinio divino, libre de agendas egoístas o duplicidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1506', 'spa', 'sincero, puro, sin mezcla, sin hipocresía', 'Este adjetivo significa puro, sin mezcla, o sincero, originalmente describiendo algo sin aleación o contaminación. Pablo lo usa en Filipenses 1:10 para describir el discernimiento de lo excelente, y 2 Pedro 3:1 lo aplica a ''mentes puras''. La palabra combina ideas de pureza y sinceridad, denotando autenticidad sin mezcla de falsedad o hipocresía. El uso antiguo abarcaba desde sustancias puras hasta carácter sincero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1507', 'spa', 'enrollar, girar, envolver, enroscar; torcer o hacer girar algo', 'Un verbo que significa girar, enrollar, torcer o enroscar algo. Aparece en diversas formas dialectales (ἑλίσσω, εἰλίσσω, ἑλίττω), todas con el sentido básico de movimiento giratorio o de torsión. El verbo describe un movimiento circular o espiral: enrollar algo, envolverlo alrededor de otro objeto o hacerlo girar. Tanto la voz activa como la media se emplean; la voz media sugiere frecuentemente que el sujeto se revuelve o gira sobre sí mismo. La voz pasiva indica ser torcido, enrollado o girado por otro agente. En contextos médicos describe articulaciones o partes del cuerpo sometidas a movimientos de torsión o rotación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1508', 'spa', 'si no, a menos que, excepto; con negaciones significa «solo» o «sino»', 'Una partícula condicional compuesta (εἰ μή) que significa «si no» o «a menos que», y que frecuentemente funciona como un marcador fuerte de excepción equivalente a «excepto» o «sino solo». Cuando introduce una excepción, delimita el único caso que no cae bajo una afirmación general, por ejemplo: «nadie puede hacer esto excepto solo Dios». Con imperativos u órdenes puede expresar condiciones urgentes. En ciertas construcciones funciona como «solo» o «sino», restringiendo el enfoque a una única opción o posibilidad. La frase combina el condicional «si» con la negación «no» para crear cláusulas de excepción fundamentales en las formulaciones teológicas y lógicas del Nuevo Testamento griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1509', 'spa', 'si no, a menos que, excepto; con negaciones equivale a «solo» o «sino»', 'Una partícula condicional compuesta (εἰ μή) cuyo significado básico es «si no» o «a menos que», pero que con gran frecuencia opera como marcador de excepción con el sentido de «excepto» o «sino solamente». Al introducir una excepción, señala el único caso que escapa a una declaración general, como en: «nadie puede hacer esto excepto solo Dios». En contextos imperativos puede expresar condiciones apremiantes. En determinadas construcciones equivale a «solo» o «sino», acotando el foco a una sola opción. Esta combinación del condicional «si» con la negación «no» resulta esencial para las cláusulas exceptivas que articulan enunciados teológicos y lógicos precisos en el griego neotestamentario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1510', 'spa', 'Ser, existir; la cópula fundamental y el verbo existencial del griego', 'Ser, existir — el verbo copulativo y existencial fundamental del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1511', 'spa', 'Ser (infinitivo); forma infinitiva del verbo «ser/estar», que expresa existencia, identidad o estado', 'Esta es la forma infinitiva del verbo griego fundamental «ser» (εἰμί), que expresa existencia, identidad, estado o predicación. En Hechos 8:37 (un versículo de autenticidad textual debatida), aparece en la declaración de Felipe sobre lo que significa «creer». Como el verbo de ser más básico, funciona en innumerables contextos gramaticales y semánticos. La evidencia multilingüe utiliza naturalmente el infinitivo equivalente de cada idioma: español «ser», francés «être», alemán «sein», el verbo más fundamental en cualquier lengua para expresar existencia e identidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1512', 'spa', 'Si en verdad; puesto que; conjunción condicional enfática que refuerza una suposición.', 'Partícula compuesta que fusiona εἰ (''si'') con πέρ (''ciertamente, en efecto''), intensificando una cláusula condicional más allá del simple ''si''. Según el contexto puede transmitir una suposición confiada (''puesto que'', como en Ro 8:9 donde la morada del Espíritu se trata como un hecho establecido) o fuerza concesiva (''aun si'', como en 1 Co 8:5). Pablo la prefiere para la argumentación teológica donde la condición enunciada se cree firmemente o se concede retóricamente. El español ''si en verdad'' y el francés ''si toutefois'' capturan este registro elevado de condicionalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1513', 'spa', 'si de algún modo, si acaso, si por algún medio; expresión de contingencia o posibilidad', 'Expresión condicional compuesta (εἰ πώς) que combina la partícula condicional «si» con «de algún modo» o «por algún medio». La frase expresa una posibilidad contingente: «si acaso» o «si de alguna manera» algo pudiera ocurrir o ser cierto. Introduce condiciones con un matiz de incertidumbre o tentatividad, sugiriendo que el hablante ve la condición como posible pero no segura. La construcción permite plantear situaciones hipotéticas en las que el modo de cumplimiento no está especificado o resulta incierto. En el Nuevo Testamento aparece frecuentemente en contextos de esperanza o deseo ferviente de que algo se cumpla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1514', 'spa', 'Estar en paz; vivir pacíficamente, mantener la armonía en las relaciones', 'Derivado de εἰρήνη (paz), este verbo llama al cultivo activo de relaciones armoniosas. Jesús lo ordena en Marcos 9:50 (''tened paz los unos con los otros'') justo después de la parábola de la sal, vinculando la pacificación con la preservación de la comunidad. Pablo lo retoma en Romanos 12:18 con el matiz realista ''si es posible, en cuanto dependa de vosotros'', y nuevamente en 2 Corintios 13:11 y 1 Tesalonicenses 5:13 como exhortación de cierre. No se trata de una paz pasiva sino de un esfuerzo sostenido e intencional por mantener la concordia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1515', 'spa', 'Paz: estado de tranquilidad, plenitud y relacion recta; equivalente griego del hebreo shalom.', 'Eirene hereda la profunda resonancia del hebreo shalom a traves de la Septuaginta, portando un peso mucho mayor que la simple ausencia de conflicto que pudiera sugerir la palabra ''paz''. En los Evangelios aparece como saludo del Cristo resucitado (''La paz sea con vosotros'', Jn 20:19, 21, 26), como don que Jesus promete a sus discipulos (Jn 14:27) y como condicion de quienes son sanados por la fe (''Ve en paz'', Mr 5:34; Lc 7:50). Pablo la desarrolla teologicamente como reconciliacion con Dios por medio de Cristo (Ro 5:1) y como fruto del Espiritu (Ga 5:22). Su amplitud abarca desde la cesacion de hostilidades politicas hasta el bienestar espiritual interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1516', 'spa', 'pacífico, apacible, que promueve la paz', 'Este adjetivo describe lo que se caracteriza por la paz o promueve relaciones pacíficas. Hebreos 12:11 lo usa para el ''fruto apacible de justicia'' que la disciplina eventualmente produce, mientras que Santiago 3:17 lo lista entre las cualidades de la sabiduría de lo alto. La palabra enfatiza carácter pacífico y disposición pacificadora más que mera ausencia de conflicto. Describe tanto estados como personas orientadas hacia el shalom.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1517', 'spa', 'Hacer la paz, efectuar reconciliación; establecer paz donde había hostilidad o separación', 'Este verbo compuesto significa hacer la paz o efectuar la reconciliación entre partes enfrentadas. En Colosenses 1:20, describe a Cristo «habiendo hecho la paz mediante la sangre de su cruz» para reconciliar todas las cosas con Dios. La palabra combina «paz» (εἰρήνη) con el verbo «hacer», creando un término específico para la acción de establecer paz. La evidencia multilingüe transmite consistentemente la creación activa de paz: español «habiendo hecho paz», alemán «Frieden machen». No se trata del mero estado de paz, sino del logro concreto de la reconciliación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1518', 'spa', 'Pacificadores, los que hacen la paz; personas que trabajan activamente para crear paz y reconciliación', 'Este sustantivo designa a los pacificadores, aquellos que trabajan activamente para crear paz y reconciliación entre las partes en conflicto. En Mateo 5:9, Jesús bendice a «los pacificadores, porque ellos serán llamados hijos de Dios». El término combina «paz» (εἰρήνη) con «hacedor», describiendo a personas caracterizadas por una labor activa de pacificación, no meramente amantes de la paz sino artífices de ella. La evidencia multilingüe muestra comprensión consistente: español «pacificadores», francés «pacificateur», transmitiendo la idea de quienes promueven activamente la paz en vez de simplemente desearla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1519', 'spa', 'A, hacia, para; hasta — la preposición direccional primaria que marca movimiento, propósito, referencia y resultado', 'A, hacia, para; hasta — la preposición direccional principal que indica movimiento, propósito, referencia y resultado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1520', 'spa', 'Uno; numeral cardinal que designa una sola entidad; también usado como ''primero'', distributivo ''cada uno'' y correlativo ''el otro''', 'Entre las palabras más fundamentales del Nuevo Testamento, εἷς porta más matices que un simple numeral. Su función principal es ''uno'', pero los Evangelios lo emplean con valor ordinal en la memorable expresión μιᾷ τῶν σαββάτων — ''el primer día de la semana'' — en los relatos de la resurrección (Mt 28:1; Mr 16:2; Lc 24:1; Jn 20:1). El español refleja el cambio con ''primer/primero'', revelando cómo los traductores perciben el paso de contar a ordenar. En construcciones más infrecuentes adquiere valor distributivo (''cada uno'', Lc 4:40) o correlativo (''el otro'', 1 Ts 5:11), donde el español lo traduce notablemente como ''otro'' en vez de ''uno''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1521', 'spa', 'Introducir, hacer entrar (a un lugar, morada o presencia); en voz pasiva: ser introducido, ser llevado adentro. El verbo griego εἰσάγω combina εἰς (''h', 'Introducir, hacer entrar (a un lugar, morada o presencia); en voz pasiva: ser introducido, ser llevado adentro. El verbo griego εἰσάγω combina εἰς (''hacia adentro'') con ἄγω (''conducir''), creando un verbo de movimiento intencional: llevar a alguien a un lugar específico. Sus apariciones en el NT van desde lo tierno —María y José llevando al niño Jesús al templo (Lc 2:27)— hasta lo urgente, cuando el señor ordena ''sal pronto y trae a los pobres'' (Lc 14:21). La palabra conlleva matices de autoridad: siempre alguien es escoltado a algún lugar con propósito. En voz pasiva (Hch 21:37; 22:24), Pablo está ''a punto de ser llevado al cuartel'', y el cambio de activa a pasiva marca la pérdida de su movimiento autónomo bajo custodia romana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1522', 'spa', 'Or y atender favorablemente; escuchar con respuesta positiva, especialmente de Dios al contestar la oracin', 'Compuesto de ''hacia'' (εἰς) y ''or'' (ἀκούω), este verbo transmite no solo el acto de escuchar sino el de escuchar con respuesta favorable, es decir, que la oracin ha sido atendida. Un ngel le dice a Zacaras que su oracin ''ha sido oda'' (Lucas 1:13), y Cornelio recibe la misma seguridad (Hechos 10:31). Jess advierte que los gentiles creen que sern ''escuchados'' por sus muchas palabras (Mateo 6:7). Hebreos 5:7 afirma que Cristo ''fue odo'' por su reverente sumisin. El francs ''exaucer'' y el alemn ''erhoeren'' captan con precisin esta dimensin de respuesta divina, distinguindola del simple acto de or.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1523', 'spa', 'Recibir, acoger, admitir; aceptar a alguien en la propia presencia o en el hogar', 'Este verbo significa recibir dentro de sí, acoger o admitir a alguien. En 2 Corintios 6:17, Dios promete «yo os recibiré» a quienes se aparten de la impureza. El uso clásico muestra que el verbo significaba admitir, recibir en espacios sagrados o acoger en comunidades. La evidencia multilingüe (español ''os recibiré'', francés ''accueillir'' = acoger, alemán ''aufnehmen'' = recibir) transmite de manera consistente la idea de recepción cordial o admisión en una relación. No se trata de un simple reconocimiento, sino de una bienvenida activa a la presencia y comunión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1524', 'spa', 'Entrar, ir adentro; pasar de fuera hacia dentro de un lugar o estructura', 'Verbo compuesto (εἰς + εἶμι, ''ir hacia dentro'') que funciona como cuasi-sinónimo de εἰσέρχομαι pero con un registro algo más formal o literario. En el libro de Hechos describe el movimiento hacia espacios sagrados e institucionales: entrar en el templo (Hch 3:3; 21:26), ir a visitar a Jacobo (Hch 21:18). Hebreos 9:6 lo emplea para la entrada regular de los sacerdotes en el tabernáculo exterior. Aparece predominantemente en Hechos y Hebreos, y comunica un ingreso deliberado a un recinto significativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1525', 'spa', 'Entrar, ir adentro, pasar; de entrada física en un lugar o entrada figurada en un estado o condición', 'Uno de los verbos de movimiento más comunes del Nuevo Testamento, que abarca desde la entrada de Jesús en una sinagoga hasta la solemne advertencia de que es difícil para un rico entrar en el reino de Dios. El sentido físico predomina — entrar en casas, ciudades, barcas y el templo — pero la extensión figurada a estados espirituales (entrar en la vida, el reposo, el gozo, el reino) posee un peso teológico enorme. Cuando Jesús dice ''entrad por la puerta estrecha'' (Mt 7:13), ambos sentidos vibran simultáneamente: la imagen física de una puerta y la realidad espiritual de entrar en el reino de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1526', 'spa', 'Son, ellos son (tercera persona plural); forma plural de ''ser'', que indica existencia o estado de múltiples sujetos', 'Esta es la tercera persona del plural del presente del verbo ''ser'' (εἰμί): ''son'' o ''ellos son''. En 1 Juan 5:7 (el Comma Johanneum, pasaje textualmente disputado), aparece en la declaración sobre los testigos. Como forma conjugada del verbo más fundamental, afirma la existencia, identidad o predicación de sujetos plurales. La evidencia multilingüe utiliza naturalmente el equivalente de tercera persona del plural de cada idioma (español ''son'', alemán ''sie sind''), la forma plural estándar de ''ser'' empleada innumerables veces en cualquier texto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1527', 'spa', 'uno, una; solo, único; el numeral 1 en todos los géneros', 'El número cardinal uno, que aparece en diversas formas dialectales (masculino εἷς, femenino μία o ἴα, neutro ἕν) a lo largo de la literatura griega. Como numeral, simplemente cuenta: un objeto, una persona, un suceso. Sin embargo, con frecuencia lleva fuerza enfática: «uno solo», «un único», sugiriendo exclusividad o singularidad. Puede reforzarse con otras palabras para mayor énfasis. Con superlativos intensifica el significado. Sirve en expresiones idiomáticas y, al repetirse, puede significar «el mismo». En el uso bíblico incluye afirmaciones teológicas de monoteísmo («un solo Dios»), enumeraciones de grupos («uno de los doce») y narraciones contables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1528', 'spa', 'Invitar a entrar, llamar adentro; convocar a alguien a pasar a la propia casa o presencia', 'Este verbo compuesto significa invitar a entrar o llamar a alguien adentro, particularmente a la propia casa. En Hechos 10:23, Pedro «los invitó a entrar» cuando llegaron los mensajeros de Cornelio. La voz media enfatiza la iniciativa personal en la invitación. El uso clásico confirma el significado de invitar a la propia casa, convocar para consulta o llamar a alguien a pasar. La evidencia multilingüe (español ''invitando adentro'', francés ''appeler'' = llamar, alemán conserva la forma griega) muestra la acción hospitalaria de dar la bienvenida a visitantes en el propio espacio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1529', 'spa', 'Entrada, acceso; tanto el acto de entrar como el medio o derecho de acceder a un lugar', 'Designa tanto el acto fsico de entrar como la acogida o bienvenida que se recibe al llegar, y tambin el derecho de acceso. Pablo habla de la ''entrada'' que tuvo entre los tesalonicenses, refirindose a su recepcin y acogida (1 Tesalonicenses 1:9; 2:1). Hebreos 10:19 declara que los creyentes tienen libre ''entrada'' al lugar santsimo por la sangre de Jess, y 2 Pedro 1:11 promete una ''entrada'' ampliamente provista en el reino eterno. Juan el Bautista proclama el arrepentimiento antes de la ''entrada'' pblica de Cristo (Hechos 13:24). El trmino abarca desde la puerta espacial hasta el derecho abstracto de acceso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1530', 'spa', 'Saltar hacia dentro, irrumpir, lanzarse; movimiento súbito e impulsivo, frecuentemente cargado de emoción', 'El verbo εἰσπηδάω combina εἰς («hacia dentro») con πηδάω («saltar»), describiendo una irrupción repentina y a menudo impulsiva en un lugar o situación. Las apariciones en el Nuevo Testamento capturan momentos de gran carga emocional: un ciego que salta al oír el llamado de Jesús, apóstoles que se rasgan las vestiduras y se lanzan entre la multitud para detener una blasfemia, y un carcelero que irrumpe temblando de urgencia. La palabra transmite inmediatez e intensidad, no una entrada casual sino un movimiento urgente y a veces desesperado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1531', 'spa', 'Entrar, pasar adentro: moverse hacia el interior de un lugar como una casa, ciudad o espacio sagrado. Εἰσπορεύομαι describe el acto fisico de entrar o', 'Entrar, pasar adentro: moverse hacia el interior de un lugar como una casa, ciudad o espacio sagrado. Εἰσπορεύομαι describe el acto fisico de entrar o pasar a un espacio, apareciendo 18 veces en el Nuevo Testamento. Construido a partir de εἰς (''hacia adentro'') y πορεύομαι (''ir, viajar''), denota movimiento direccional a traves de una entrada hacia un area definida. Marcos lo usa con mayor frecuencia: Jesus entra en la sinagoga de Capernaum (Mr 1:21), entra en una casa (Mr 5:40), y es rodeado por multitudes al entrar en aldeas (Mr 6:56). En Marcos 4:19, la palabra se desplaza a un registro figurado cuando ''los deseos de otras cosas entran'' y ahogan la palabra. Hechos registra a personas ''entrando y saliendo'' como descripcion de la vida comunitaria entre los creyentes (Hch 9:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1532', 'spa', 'Correr hacia adentro, entrar corriendo; moverse rápidamente hacia un espacio corriendo', 'Este verbo compuesto significa correr hacia adentro o entrar precipitadamente. En Hechos 12:14, la sirvienta Rode «corrió adentro» tras reconocer la voz de Pedro en la puerta, tan emocionada que olvidó abrir. El participio describe el movimiento rápido hacia el interior de la casa. El uso clásico confirma este sentido para correr hacia edificios, barcos entrando en puertos o condiciones que irrumpen en el cuerpo. La evidencia multilingüe (español ''corriendo adentro'', francés ''entrer en courant'' = entrar corriendo) capta tanto la velocidad como la dirección del movimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1533', 'spa', 'Introducir, llevar adentro; también conducir a una situación, especialmente a la tentación o prueba.', 'Verbo compuesto (εἰς + φέρω) que significa llevar o introducir algo dentro de un espacio o situación. En su sentido físico aparece cuando unos amigos intentan meter a un paralítico en la casa donde Jesús enseña (Lc 5:18-19), y cuando Pablo observa que nada trajimos al mundo ni nada podremos sacar (1 Ti 6:7). El uso teológicamente más relevante se encuentra en el Padrenuestro: «no nos metas en tentación» (Mt 6:13; Lc 11:4), donde el verbo pasa del movimiento espacial a la exposición situacional. En Lucas 12:11 describe ser llevado ante las autoridades de la sinagoga, un «introducir» social más que puramente físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1534', 'spa', 'Luego, después; un adverbio temporal que marca la secuencia en una serie de eventos o argumentos. εἶτα es un adverbio de secuenciación que señala el p', 'Luego, después; un adverbio temporal que marca la secuencia en una serie de eventos o argumentos. εἶτα es un adverbio de secuenciación que señala el paso siguiente en una narración o argumento. Funciona como ''luego'' o ''después'' en español, colocando eventos o ideas en sucesión ordenada sin necesariamente implicar causalidad. Marcos lo usa para describir las etapas del crecimiento del grano — primero la hierba, luego (εἶτα) la espiga, después el grano lleno (Mr 4:28). Pablo lo emplea prominentemente en 1 Corintios 15:5-7 para secuenciar las apariciones de la resurrección y en 15:24 para el orden escatológico. También puede introducir el siguiente punto en un argumento (1 Ti 2:13; He 12:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1535', 'spa', 'Sea...o, ya sea...ya sea: conjuncion disyuntiva que presenta alternativas como igualmente posibles o equivalentes.', 'La conjuncion eite (''sea...o'') aparece tipicamente en forma duplicada —eite...eite— para presentar dos o mas alternativas como igualmente posibles o equivalentes. Pablo recurre con frecuencia a esta construccion para catalogar la irrelevancia de las distinciones ante Cristo: ''sea judios o griegos, sea esclavos o libres'' (1 Co 12:13), ''sea que vivamos o que muramos, del Senor somos'' (Ro 14:8), y el amplio inventario de 1 Co 3:22: ''sea Pablo, sea Apolos, sea Cefas, sea el mundo, sea la vida, sea la muerte''. La forma espanola sea...sea replica con precision la disyuncion equilibrada del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1536', 'spa', 'si alguien, si algo; quienquiera, cualquiera; alguno, alguna cosa (indefinido)', 'Pronombre compuesto indefinido (εἴ τις) que combina la partícula condicional con un pronombre indefinido para significar «si alguien» o «si algo». La construcción crea condiciones indefinidas, refiriéndose a cualquier persona o cosa que pudiera cumplir los criterios indicados, sin identificar a un individuo concreto. Permite enunciar principios generales: «si alguien hace X, entonces Y sucede». También funciona simplemente como pronombre indefinido —«alguien», «algo», «cualquiera»— en contextos donde la identidad específica no importa. Es una herramienta fundamental para declaraciones universales o generales, tanto en contextos condicionales como no condicionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1537', 'spa', 'De, desde dentro; indica origen, procedencia, causa, materia, extracción partitiva y punto de partida temporal', 'Una preposición que indica movimiento o procedencia desde el interior de algo, expresando origen, fuente, causa, el material del que algo está hecho, una parte de un todo, o el inicio de un período de tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1538', 'spa', 'Cada uno, cada cual: pronombre distributivo que singulariza a los miembros individuales de un grupo.', 'El griego hekastos es un adjetivo y pronombre distributivo que senala a los individuos uno por uno dentro de un conjunto colectivo: ''cada uno'' o ''cada cual''. A diferencia de pas (''todos'', que enfatiza la totalidad), hekastos subraya la responsabilidad o participacion individual. Esta distincion es teologicamente significativa en pasajes como Mt 18:35 (''si cada uno de vosotros no perdona de corazon a su hermano'') y 1 Co 3:8 (''cada uno recibira su propia recompensa''). Aparece 82 veces en el Nuevo Testamento, frecuentemente en contextos de juicio, responsabilidad o dones individuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1539', 'spa', 'Cada vez, en cada ocasión; en cada instancia o siempre que algo ocurre', 'Este adverbio significa ''cada vez'' o ''en cada ocasión'': un marcador temporal para instancias recurrentes. En 2 Pedro 1:15, Pedro promete asegurarse de que los creyentes puedan «en cada ocasión» después de su muerte recordar estas enseñanzas. La palabra combina ''cada'' (ἕκαστος) con un sufijo temporal, creando una expresión para cada ocurrencia o instancia. La evidencia multilingüe (español ''cada vez'', alemán ''jedesmal'' = cada vez, francés simplemente transliteró) transmite el sentido temporal distributivo: no de una vez por todas, sino repetidamente, en cada instancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1540', 'spa', 'Cien; el numero cardinal cien. Ἑκατόν es el numero cardinal griego indeclinable que significa ''cien.'' Aparece en parabolas sobre rendimientos extraord', 'Cien; el numero cardinal cien. Ἑκατόν es el numero cardinal griego indeclinable que significa ''cien.'' Aparece en parabolas sobre rendimientos extraordinarios — la cosecha del ciento por uno de la buena semilla (Mt 13:8, 23; Mr 4:8, 20) — y en ensenanzas sobre el cuidado de Dios por cada individuo: dejar noventa y nueve ovejas para buscar la que se perdio (Mt 18:12; Lc 15:4). Tambien cuantifica deudas en la parabola del siervo que no perdona (Mt 18:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1541', 'spa', 'De cien años de edad; que describe a alguien que ha alcanzado el centenario de vida', 'Este adjetivo compuesto significa ''de cien años de edad'', describiendo a quien ha completado un siglo de vida. En Romanos 4:19, Pablo señala que Abraham tenía ''cerca de cien años'' al considerar la incapacidad natural de su cuerpo para engendrar hijos, antes de la concepción milagrosa de Isaac. El término combina ''cien'' (ἑκατόν) con ''años'' (ἔτος), formando un descriptor de edad. La evidencia multilingüe es uniforme: español ''de cien años'', francés ''cent ans'', alemán ''hundertjährig'', todas expresiones que reflejan literalmente ''centenario''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1542', 'spa', 'Cien veces más, céntuplo; multiplicación exponencial como bendición divina sobre el sacrificio', 'El adjetivo ἑκατονταπλασίων (de ἑκατόν «cien» + πλάσιος «veces») significa multiplicado cien veces. En la enseñanza de Jesús describe el retorno extravagante de lo que se entrega por el reino: no una recompensa modesta, sino una abundancia desbordante. La multiplicación al céntuplo evoca la imaginería veterotestamentaria de la cosecha (Génesis 26:12, Isaac cosechando el céntuplo) y señala una bendición divina que supera con creces todo cálculo o expectativa humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1543', 'spa', 'Centurión; oficial militar romano al mando de aproximadamente cien soldados.', 'Centurión; oficial militar romano al mando de aproximadamente cien soldados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1544', 'spa', 'Echar fuera, expulsar (esp. demonios); arrojar, sacar, producir, enviar', 'El verbo por excelencia del exorcismo neotestamentario, ἐκβάλλω combina ἐκ (''fuera de'') con βάλλω (''lanzar''), produciendo un término que casi siempre implica energía y urgencia. Jesús echa fuera demonios con una palabra (Mt 8:16), los fariseos lo acusan de hacerlo por Beelzebú (Mt 9:34) y los Doce reciben la misma autoridad (Mt 10:1). Pero su alcance va más allá del exorcismo: sacar una paja del ojo ajeno (Mt 7:4-5), arrojar al siervo a las tinieblas (Mt 25:30), sacar tesoros de un depósito (Mt 13:52) y la imagen del pastor que ''saca'' a sus ovejas (Jn 10:4). La tensión entre expulsión violenta y despliegue deliberado le confiere una versatilidad dramática singular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1545', 'spa', 'una salida, resultado o desenlace; el fin de una situación, ya sea como liberación o como término de la vida', 'El sustantivo ἔκβασις (de ἐκβαίνω, ''salir'') designa una salida, escape o desenlace. Originalmente espacial (un desembarcadero, un paso de montaña), su significado se amplió para referirse al resultado final de los acontecimientos, incluyendo el término de la vida de una persona. En el uso bíblico se destaca tanto la salida que Dios provee ante la tentación como el desenlace observable de la vida de líderes fieles: cómo terminan las cosas, ya sea como escape del peligro o como testimonio consumado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1546', 'spa', 'Echazón, lanzamiento de carga al mar; acción de arrojar la mercancía de un barco para aligerarlo', 'Este sustantivo designa la echazón o el acto de arrojar carga por la borda de un barco, generalmente para aligerarlo durante una tempestad. En Hechos 27:18, durante el tormentoso viaje de Pablo, la tripulación ''hizo una echazón'' lanzando la carga al mar. El término proviene del verbo ''echar fuera'', y el uso clásico confirma su sentido náutico de descarga de emergencia, aunque también podía significar expulsión o despido en sentido más amplio. La evidencia multilingüe refleja distintos enfoques para esta medida de emergencia marítima: español ''descarga'', francés ''naufrage'', alemán ''Ladung über Bord werfen''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1547', 'spa', 'ser dado/a en matrimonio (pasivo); dar en matrimonio (sentido activo implícito)', 'Verbo relacionado con las transacciones matrimoniales, específicamente el acto de entregar a alguien (generalmente una hija) en matrimonio. La voz pasiva enfatiza la perspectiva de quien es dado/a en casamiento, es decir, quien recibe la acción de ser entregado/a a un cónyuge, en lugar de iniciar el matrimonio por cuenta propia. El sentido activo designa el acto de dar a alguien en matrimonio, típicamente por parte de un padre o tutor que concerta la unión. Esto refleja la estructura social del antiguo Mediterráneo, donde los matrimonios eran arreglados por las familias y las mujeres eran «entregadas» de un hogar a otro mediante procesos formales de compromiso y boda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1548', 'spa', 'ser dado/a en matrimonio (pasivo); dar en matrimonio (sentido activo implícito)', 'Verbo vinculado a las transacciones matrimoniales, que denota la acción de entregar a alguien —por lo general una hija— en matrimonio. En voz pasiva subraya la perspectiva de la persona que es entregada en casamiento, quien recibe la acción en vez de iniciarla. En sentido activo, describe el acto del padre o tutor que dispone la unión conyugal. Este término captura la realidad social del Mediterráneo antiguo, donde los matrimonios eran concertados por las familias y las mujeres pasaban formalmente de un hogar a otro a través de los procesos de esponsales y celebración nupcial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1549', 'spa', 'Nietos, descendientes; hijos de los propios hijos, la siguiente generación', 'Este adjetivo, usado como sustantivo, significa ''descendientes'' y en particular ''nietos'', es decir, los hijos de los propios hijos. En 1 Timoteo 5:4, Pablo instruye que si una viuda tiene ''nietos'', estos deben aprender a mostrar piedad hacia su propia familia cuidando de su abuela. El término literalmente significa ''nacido de'' (ἔκγονος), y el uso clásico confirma que podía referirse a hijos, descendientes en general o específicamente nietos. La evidencia multilingüe es consistente: español ''nietos'', alemán ''Enkel'', todos expresando esa relación generacional de segundo grado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1550', 'spa', 'Ser gastado, consumido; ser agotado o expendido por completo, especialmente de recursos o de uno mismo', 'Este verbo significa agotar o gastar por completo, ser consumido hasta el fin. En 2 Corintios 12:15, Pablo declara que con gusto ''gastará y será gastado'' por las almas de los corintios, entregando no solo sus recursos sino a sí mismo. La forma pasiva enfatiza el ser expendido o agotado completamente. El uso clásico confirma este sentido para el agotamiento de provisiones, el drenaje de fluidos corporales o la depleción de recursos. La evidencia multilingüe transmite esa expendición total: español ''seré gastado'', francés ''dépenser'', alemán ''sich völlig ausgeben'', frecuentemente con matices de sacrificio personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1551', 'spa', 'Esperar algo con expectativa y paciencia; aguardar un resultado anticipado con disposicion activa.', 'Describe una postura de espera activa y expectante, no una inactividad pasiva sino una anticipacion con proposito. En Juan 5:3 los enfermos junto al estanque de Betesda aguardan el movimiento del agua; en Hechos 17:16 Pablo espera a sus companeros en Atenas mientras su espiritu se conmueve ante los idolos de la ciudad. En las cartas a los Corintios el verbo se emplea para la cortesia cristiana practica: esperarse unos a otros en la Cena del Senor (1 Co 11:33) y despedir a Timoteo en paz (1 Co 16:11). Hebreos 10:13 eleva el termino a su cumbre teologica: Cristo esta sentado a la diestra de Dios, esperando hasta que sus enemigos sean puestos por estrado de sus pies.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1552', 'spa', 'Evidente, manifiesto, completamente claro; patente y obvio para todos los observadores', 'Este adjetivo significa evidente, conspicuo o completamente claro, siendo una forma intensificada de ''claro'' (δῆλος). En 2 Timoteo 3:9, Pablo declara que la insensatez de los falsos maestros ''será evidente para todos'', haciéndose manifiesta. El prefijo intensifica el significado básico hasta ''totalmente claro'' o ''patente''. El uso clásico confirma este sentido para cosas conspicuas, notables o manifiestamente claras. La evidencia multilingüe es coherente: español ''evidente'', alemán ''offenkundig'' (abiertamente conocido), todos transmitiendo claridad completa y ausencia total de ambigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1553', 'spa', 'estar fuera de casa, estar ausente, vivir en el exilio; específicamente, la ausencia del cuerpo como peregrinaje lejos del hogar celestial', 'El verbo ἐκδημέω (de ἐκ + δῆμος, ''lejos del pueblo propio'') significa estar en el extranjero, lejos de la patria, o en el exilio. En el uso clásico se refería a viajes al extranjero o al destierro. Pablo lo emplea para describir la existencia terrenal del creyente como un exilio temporal lejos de su verdadero hogar con el Señor. La palabra crea un contraste conmovedor: mientras estamos ''en casa en el cuerpo'', estamos simultáneamente ''ausentes del Señor'', haciendo de la vida presente una especie de residencia extranjera a la espera del regreso definitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1554', 'spa', 'Arrendar, dar en arriendo; en voz media, alquilar una propiedad (especialmente una viña) a labradores', 'Aunque la forma activa de ἐκδίδωμι significa ''entregar'' o ''dar fuera'', todas las apariciones en el NT emplean la voz media con el sentido específico de arrendar propiedad agrícola. Las cuatro ocurrencias se encuentran en la Parábola de los Labradores Malvados (Mt 21:33, 41; Mc 12:1; Lc 20:9), donde un terrateniente planta una viña y la arrienda a labradores. El español ''arrendar'' y el francés ''louer'' reflejan fielmente el sentido contractual-agrícola del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1555', 'spa', 'relatar detalladamente, describir exhaustivamente, narrar completamente', 'Este verbo compuesto significa relatar o describir algo con pleno detalle. Hechos lo usa dos veces: Habacuc 1:5 (citado en Hechos 13:41) desafía a los oyentes a reportar lo que Dios hará, y Hechos 15:3 describe cómo Pablo y Bernabé detallan las conversiones de los gentiles. El prefijo ''ek-'' intensifica el verbo básico, enfatizando la exhaustividad y completitud en la narración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1556', 'spa', 'Vengar o ejecutar justicia retributiva a favor del agraviado; tambien vindicar u otorgar justicia al oprimido.', 'Un verbo que recorre todo el espectro de la justicia, desde la retribucion severa hasta la vindicacion compasiva. En Romanos 12:19 Pablo advierte a los creyentes que no se venguen a si mismos, reservando la venganza para Dios, y en Apocalipsis 6:10 y 19:2 los martires claman para que Dios vengue su sangre derramada. Sin embargo, en la parabola de la viuda persistente (Lc 18:3, 5), el mismo verbo adquiere un matiz mas suave pero igualmente urgente: vindicar, hacer justicia a quien ha sido agraviado. La viuda no busca castigo, sino que se le reconozcan sus derechos. La expresion ''Hazme justicia'' capta hermosamente como este termino griego abarca desde la retribucion hasta la restauracion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1557', 'spa', 'Venganza, retribución; vindicación o justicia para el agraviado; castigo judicial por parte de las autoridades.', 'Sustantivo que designa la ejecución de la justicia, ya sea divina, comunitaria o gubernamental. Cuando Dios declara «mía es la venganza» (Ro 12:19), ἐκδίκησις apunta a la retribución soberana contra la maldad. Sin embargo, cuando la viuda insistente clama por justicia (Lc 18:7-8), la misma palabra gira hacia la vindicación del oprimido, y el español cambia reveladoramente a «justicia». En contextos cívicos como 1 Pedro 2:14, describe el castigo que los gobernantes administran contra los malhechores — un acto judicial, no personal ni divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1558', 'spa', 'vengador, el que ejecuta justicia o castigo', 'Este adjetivo usado sustantivamente significa vengador o quien mantiene la justicia mediante el castigo. Pablo lo usa en Romanos 13:4 para referirse a la autoridad gobernante como siervo de Dios y vengador que ejecuta la ira, y en 1 Tesalonicenses 4:6 para el Señor como vengador de la inmoralidad sexual. El término enfatiza la vindicación activa del bien y el castigo del mal, ya sea mediante autoridades humanas o juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1559', 'spa', 'Perseguir, expulsar, ahuyentar; perseguir con intención hostil o expulsar por la fuerza', 'Este verbo compuesto significa ahuyentar, expulsar por la fuerza o perseguir. En 1 Tesalonicenses 2:15, Pablo describe a los judíos que mataron a Jesús y a los profetas como aquellos que «nos expulsaron» y desagradan a Dios. El verbo combina un prefijo intensivo con «perseguir/dar caza», creando un término para la expulsión agresiva o la persecución. El uso clásico confirma significados de desterrar, ahuyentar o atacar y perseguir. La evidencia multilingüe (español «que persiguieron», francés y alemán ambos significan «perseguir/dar caza») transmite la idea de persecución hostil o expulsión forzosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1560', 'spa', 'Entregado, puesto en manos de otro; traicionado o rendido al poder o autoridad de otro', 'Este adjetivo significa entregado, rendido o traicionado, es decir, puesto en manos y bajo el poder de otro. En Hechos 2:23, Pedro declara que Jesús fue «entregado conforme al plan determinado de Dios» para ser crucificado. El término proviene de «dar/entregar» y el uso clásico muestra que significaba traicionado, puesto en manos de otro, o entregado en matrimonio. La evidencia multilingüe (español «entregado», francés «livrer» = entregar) transmite de manera constante la transferencia de una persona al control de otro, a menudo con matices de traición o rendición ante poderes hostiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1561', 'spa', 'Expectación, espera ansiosa; estado de anticipar algo, especialmente con intensidad', 'Este sustantivo significa expectación o espera ansiosa de algo que se anticipa. En Hebreos 10:27, describe «una horrenda expectación de juicio» que aguarda a quienes persisten en el pecado. La palabra proviene de «parecer/pensar» y originalmente significaba expectativa u opinión. El uso clásico muestra que abarcaba expectación, anticipación, noción u opinión, es decir, lo que uno espera o piensa que ocurrirá. La evidencia multilingüe (español «expectación», francés «attente» = espera, alemán «Erwartung» = expectativa) transmite la anticipación orientada al futuro, aunque en Hebreos se usa para una expectativa terrible más que esperanzadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1562', 'spa', 'Desvestir, despojar de ropa; desnudar a alguien quitndole las vestiduras; metafricamente, quedar despojado', 'Un trmino vvido para quitar las vestiduras a uno mismo o a otra persona, frecuentemente por la fuerza. En los Evangelios describe a los soldados romanos despojando a Jess de sus ropas durante la Pasin (Mateo 27:28, 31; Marcos 15:20), y a los salteadores desnudando al viajero herido en la parbola del Buen Samaritano (Lucas 10:30). Pablo lo emplea metafricamente en 2 Corintios 5:4, donde ser ''desvestido'' representa la vulnerabilidad de la muerte antes de recibir el cuerpo de resurreccin. El espaol ''desnudar'' y el francs ''dpouiller'' captan el sentido de exposicin forzada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1563', 'spa', 'Allí — adverbio de lugar que señala una ubicación distante del hablante; a veces con sentido de dirección', 'Ἐκεῖ es el adverbio griego común que significa ''allí, en aquel lugar'', y el Nuevo Testamento lo emplea con notable frecuencia en contextos narrativos. Sitúa la estancia de la sagrada familia en Egipto (''quédate allí hasta que yo te diga'', Mt 2:13), marca lugares de reunión y enseñanza (''donde están dos o tres reunidos, allí estoy yo'', Mt 18:20) y fija puntos geográficos en la narración evangélica. Ocasionalmente porta un matiz direccional — ''ir allá'' — absorbiendo la función del más raro ἐκεῖσε. Su peso teológico emerge del contexto más que de la semántica: es el ''allí'' de la presencia divina, del juicio o del refugio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1564', 'spa', 'De allí, desde allí -- adverbio espacial que indica partida o movimiento desde un lugar previamente mencionado.', 'De allí, desde allí -- adverbio espacial que indica partida o movimiento desde un lugar previamente mencionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1565', 'spa', 'Aquel, aquella, aquello; pronombre demostrativo distal que señala a persona o cosa mencionada previamente, a menudo con fuerza enfática', 'Ἐκεῖνος es el pronombre demostrativo griego para ''aquella persona'' o ''aquella cosa de allá'' — el par distal de οὗτος (''este''). En los Evangelios conlleva un peso teológico significativo, especialmente en Juan, donde ''aquel'' (ἐκεῖνος) se refiere frecuentemente a Jesús, al Espíritu o al Padre con una especie de distancia reverencial: ''Cuando venga el Espíritu de verdad, aquel os guiará a toda la verdad'' (Jn 16:13). Usado como atributo (''aquel día'', ''aquella hora''), marca distancia temporal o narrativa respecto al hablante. Usado sustantivamente, funciona como pronombre enfático de tercera persona, a menudo contrastivo. El español ''aquel'' preserva fielmente la cualidad distal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1566', 'spa', 'allí, a aquel lugar, hacia allá', 'Este adverbio indica dirección o ubicación ''allí'' o ''a aquel lugar''. En Hechos 21:3 describe el barco navegando a Tiro, y en 22:5 Pablo menciona ir a Damasco. La palabra enfatiza movimiento direccional hacia un destino ya indicado en el contexto. El uso clásico a veces lo empleaba para ''al otro mundo'', pero las ocurrencias en el Nuevo Testamento son directamente geográficas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1567', 'spa', 'Buscar con diligencia y fervor (especialmente a Dios); demandar cuentas, requerir (especialmente culpa de sangre).', 'El verbo ἐκζητέω intensifica el comun ζητέω (''buscar'') con el prefijo ἐκ-, produciendo un termino que transmite minuciosidad, urgencia y rendicion final de cuentas. En su sentido dominante, describe la busqueda ferviente de Dios o de realidades espirituales: las naciones que ''buscaran'' al Senor (Hch 15:17, citando Am 9:12), la solemne observacion de que ''nadie busca a Dios'' (Ro 3:11), y la promesa de que Dios ''recompensa a los que le buscan con diligencia'' (He 11:6). Pero un sentido juridico distinto emerge en Lucas 11:50-51, donde Jesus advierte que la sangre de todos los profetas ''sera demandada'' a esta generacion, evocando el lenguaje de la LXX donde Dios ''requiere la sangre'' del culpable (Gn 9:5; 2 S 4:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1568', 'spa', 'Quedarse intensamente asombrado o alarmado; experimentar una mezcla de estupor y angustia', 'Forma intensificada de θαμβέω (asombrarse), este verbo aparece solo en el Evangelio de Marcos y conlleva una carga emocional más fuerte que la simple sorpresa. Cuando la multitud ve a Jesús tras la Transfiguración, quedan sobrecogidos de asombro (Mc 9:15). En Getsemaní, Jesús mismo comienza a sentirse ''grandemente angustiado'' (Mc 14:33), revelando que esta palabra une el asombro con la aflicción. Las mujeres en el sepulcro vacío lo experimentan como una mezcla de terror y admiración (Mc 16:5-6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1569', 'spa', 'Sumamente asombrado, atónito, pasmado; sobrecogido de admiración o temor más allá del asombro común', 'Este adjetivo significa sumamente asombrado o completamente atónito, una forma intensificada de «asombrado». En Hechos 3:11, la multitud quedó «grandemente asombrada» por la sanación del hombre cojo realizada por Pedro y Juan. El prefijo intensifica el sentido básico de asombro hasta convertirlo en estupefacción abrumadora. El uso clásico confirma que podía significar asombrado, atónito o terrible, aterrador, abarcando extremos de respuesta emocional tanto en admiración como en temor. La evidencia multilingüe (español «asombrados», francés «très étonné» = muy asombrado) transmite de manera uniforme un asombro intensificado que supera la sorpresa ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1570', 'spa', 'Expuesto, abandonado; dejado a la intemperie, especialmente de infantes abandonados para morir', 'Este adjetivo significa expuesto o echado fuera, utilizado particularmente para referirse a infantes abandonados. En Hechos 7:19, Esteban describe cómo el Faraón obligaba a los hebreos a exponer a sus bebés para que murieran. El término proviene de «poner fuera» y el uso clásico confirma que significaba enviado lejos, expuesto (especialmente de niños no deseados) o desechado. La evidencia multilingüe (español «expuestos», francés «exposé», inglés «exposed») transmite de manera consistente la cruel práctica del abandono infantil. Esta era una realidad sombría del mundo antiguo: niños no deseados dejados a la intemperie para morir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1571', 'spa', 'limpiar completamente, purificar, eliminar por completo', 'Este verbo compuesto significa limpiar o purificar exhaustivamente. Pablo lo usa en 1 Corintios 5:7 mandando a los creyentes a ''limpiar la vieja levadura'', y 2 Timoteo 2:21 habla de limpiarse uno mismo de asociaciones deshonrosas. El prefijo ''ek-'' intensifica la purificación, sugiriendo remoción completa en lugar de limpieza superficial. El uso antiguo incluía limpiar tierra de monstruos y pulir estatuas a la perfección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1572', 'spa', 'Encenderse, arder en pasión; inflamarse de deseo intenso, particularmente de pasión sexual', 'Este verbo significa arder, encenderse o inflamarse, especialmente con pasión intensa. En Romanos 1:27, Pablo describe a hombres que ''se encendieron en su lascivia unos con otros.'' El término puede referirse a un fuego literal que se enciende, pero con mayor frecuencia se usa metafóricamente para describir el arder de emociones intensas, en particular la lujuria o la ira. El uso clásico confirma tanto la combustión literal (ojos quemados, fuegos encendidos) como la metafórica (inflamado de curiosidad, provocado a ira). La evidencia multilingüe (español ''se encendieron,'' francés ''brûler,'' alemán ''entbrennen'') transmite el encendimiento intenso de la pasión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1573', 'spa', 'Desmayar, perder el animo, cansarse o desalentarse ante la dificultad o el esfuerzo prolongado.', 'Este verbo transmite el agotamiento emocional y espiritual que sobreviene bajo una presion sostenida, y advierte contra el decaimiento de la resolucion. Jesus lo utiliza para enmarcar la parabola de la viuda persistente: orar y ''no desmayar'' (Lc 18:1). Pablo retoma la exhortacion a lo largo de sus cartas: no desmayamos en el ministerio (2 Co 4:1, 16), ni en hacer el bien (Ga 6:9), ni bajo la tribulacion (Ef 3:13). La imagen es la de un marchitamiento interior de la voluntad, no mera fatiga fisica, sino un desfallecimiento del alma que la fe perseverante debe resistir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1574', 'spa', 'traspasar, atravesar, perforar', 'Este verbo significa traspasar o atravesar con un arma. Ambas ocurrencias en el Nuevo Testamento se refieren a la crucifixión de Cristo: Juan 19:37 cita Zacarías 12:10 sobre mirar al que traspasaron, y Apocalipsis 1:7 hace eco de esta profecía. La palabra originalmente significaba pinchar o sacar (como los ojos), pero desarrolló el sentido más fuerte de traspasar con un arma. Captura la violencia de la herida de la crucifixión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1575', 'spa', 'desgajar, quebrar (especialmente ramas); en voz pasiva, ser arrancado o separado violentamente de una conexión', 'Pablo emplea esta metáfora agrícola exclusivamente en Romanos 11 para describir la separación de los israelitas infieles del olivo del pueblo del pacto de Dios. El verbo capta tanto la violencia como la finalidad de desgajar ramas vivas: no se trata de una poda suave, sino de una remoción forzosa. Algunas ramas naturales ''fueron desgajadas'' para dar lugar a los injertos de olivo silvestre (11:17), abriendo espacio para la inclusión de los gentiles. Pablo advierte contra la arrogancia al señalar que Dios desgajó las ramas naturales por causa de la incredulidad (11:19-20), estableciendo el principio de que la conexión depende de la fe, no del privilegio étnico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1576', 'spa', 'excluir, cerrar el acceso, impedir la entrada', 'Este verbo significa excluir o cerrar el acceso a algo. Pablo lo usa en Romanos 3:27 al preguntar si se ha excluido la jactancia, y en Gálatas 4:17 al describir a maestros falsos que quieren cerrar el acceso a los creyentes. La palabra puede referirse a un cierre físico o a una exclusión metafórica de la participación. El uso antiguo incluía excluir de alianzas, impedir recibir algo, o bloquear oportunidades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1577', 'spa', 'Asamblea, congregación — generalmente la iglesia cristiana (local o universal); también cualquier asamblea reunida, incluida la de Israel en el desierto', 'Ἐκκλησία, enraizada en la asamblea cívica griega de ciudadanos ''convocados'', se convirtió en el término definitorio del Nuevo Testamento para la comunidad de creyentes. En 105 de sus 114 apariciones designa la iglesia cristiana — desde congregaciones domésticas locales (Ro 16:5; 1 Co 16:19) hasta la visión paulina del cuerpo universal de Cristo (Ef 1:22-23; Col 1:18). El español ''iglesia'' deriva directamente de este uso cristiano especializado. Sin embargo, nueve pasajes conservan el sentido más antiguo y no técnico: Esteban llama a Israel en el desierto ''la congregación en el desierto'' (Hch 7:38), y el secretario de Éfeso remite a la multitud tumultuosa a la ''asamblea legítima'' (Hch 19:39). El uso de Jesús en Mt 16:18 y 18:17 se sitúa en el umbral entre ambos sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1578', 'spa', 'apartarse, desviarse, evitar; desviación deliberada de un camino, una norma o una asociación', 'El verbo compuesto ἐκκλίνω (ἐκ + κλίνω, ''inclinar'') significa apartarse, desviarse o evitar; originalmente espacial, se extendió al ámbito moral y relacional. El uso bíblico subraya el acto deliberado de apartarse: toda la humanidad desviándose del camino de Dios (Romanos 3), la instrucción de evitar a personas divisivas (Romanos 16) y el consejo de apartarse del mal para buscar el bien (1 Pedro 3). La palabra implica una decisión consciente de cambiar de rumbo, ya sea destructivamente (alejándose de la justicia) o protectoramente (alejándose del mal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1579', 'spa', 'Nadar hacia afuera, escapar nadando; alejarse a nado, especialmente desde un barco hacia la orilla', 'Este verbo compuesto significa nadar hacia afuera o escapar nadando, particularmente desde un navío hacia la orilla. En Hechos 27:42, los soldados planeaban matar a los presos para que ninguno ''escapara nadando'' durante el naufragio. El verbo combina el prefijo ''fuera de'' con ''nadar,'' creando un término para alejarse a nado de algo, típicamente de un barco hacia tierra firme. El uso clásico confirma este sentido de lanzarse al mar desde una embarcación o nadar hasta la costa. La evidencia multilingüe (español ''habiendo nadado,'' francés ''nager'') transmite la acción de nadar, aunque no siempre preserva el matiz direccional del prefijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1580', 'spa', 'Sacar llevando, transportar hacia fuera; llevar un cadáver para su entierro, conducir un cortejo fúnebre', 'Este verbo significa sacar llevando o transportar hacia afuera, empleado especialmente para llevar cadáveres al entierro. En Lucas 7:12, Jesús se encuentra con un difunto que ''era llevado'' para ser sepultado en Naín. El compuesto combina ''fuera de'' con ''llevar,'' y el uso clásico lo confirma tanto para sacar cosas a un lugar seguro como para conducir un cadáver al sepulcro o perseverar hasta el final. La evidencia multilingüe (español ''era llevado,'' francés ''emporter'') transmite el movimiento de sacar algo, típicamente en contextos funerarios dentro del uso bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1581', 'spa', 'Cortar, talar (un árbol en juicio); cortar, amputar (un miembro o rama, separando la parte del todo). ἐκκόπτω se divide claramente entre talar un árbo', 'Cortar, talar (un árbol en juicio); cortar, amputar (un miembro o rama, separando la parte del todo). ἐκκόπτω se divide claramente entre talar un árbol entero y separar una parte de un todo. La advertencia de Juan el Bautista de que ''todo árbol que no da buen fruto es cortado'' (Mt 3:10; Lc 3:9) estableció una poderosa metáfora de juicio divino que Jesús extiende (Mt 7:19; Lc 13:7, 9) —siempre árboles enteros bajo el hacha. Pero Jesús también ordena cortar la mano o el pie que hace pecar (Mt 5:30; 18:8), y Pablo usa la metáfora del olivo donde las ramas son ''desgajadas'' por incredulidad (Ro 11:22, 24). En 2 Corintios 11:12, Pablo metafóricamente ''corta'' la oportunidad de los falsos apóstoles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1582', 'spa', 'Estar pendiente de, aferrarse a; estar suspendido de algo con atención intensa, escuchar absorto', 'Este verbo significa colgar de algo o estar suspendido, y particularmente estar pendiente de las palabras de alguien con atención absorta. En Lucas 19:48, el pueblo ''estaba pendiente'' de las palabras de Jesús, escuchando con tal intensidad que parecían suspendidos de su enseñanza. El sentido literal es colgar o estar suspendido de algo, pero metafóricamente describe una atención devota o un apego ferviente. El uso clásico confirma tanto el sentido literal de colgar de algo como el figurado de entregarse con devoción a una persona o causa. La evidencia multilingüe (español ''estaba pendiente,'' francés ''être suspendu'') preserva la vívida metáfora de estar colgado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1583', 'spa', 'Divulgar, revelar abiertamente; hablar de algo públicamente, a veces con connotación de indiscreción', 'Este verbo significa divulgar, revelar o hablar abiertamente sobre algo. En Hechos 23:22, el tribuno ordena al sobrino de Pablo ''que a nadie dijera'' que le había revelado la conspiración contra Pablo. El uso clásico muestra que podía significar soltar la lengua, delatar o divulgar, a veces con connotaciones de locuacidad o indiscreción. La evidencia multilingüe (español ''digas,'' francés ''déclarer'') transmite la acción de hablar, aunque sin la connotación negativa del sentido clásico de ''irse de la lengua.'' En este contexto simplemente se trata de mantener la información en secreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1584', 'spa', 'Resplandecer, brillar intensamente; irradiar luz o gloria, distinguirse por su resplandor radiante', 'Este verbo significa resplandecer o irradiar luz con intensidad. En Mateo 13:43, Jesús declara que «los justos resplandecerán como el sol» en el reino de su Padre. El compuesto combina «fuera de» con «brillar», enfatizando una radiancia que sale hacia afuera. El uso clásico confirma significados de brillar, emitir destellos, irrumpir con fuerza (de fiebre o sonido) y distinguirse. La evidencia multilingüe (español «resplandecerán», francés «resplendir») transmite consistentemente una brillantez radiante, frecuentemente con matices de glorificación escatológica en el uso bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1585', 'spa', 'Olvidar por completo, olvidar totalmente; perder toda memoria o conciencia de algo previamente conocido', 'Este verbo significa olvidar por completo o totalmente, una forma intensificada de «olvidar». En Hebreos 12:5, el autor pregunta retóricamente si los lectores «han olvidado del todo» la exhortación que se dirige a ellos como hijos. El prefijo refuerza el olvido básico hasta convertirlo en un desvanecimiento total de la memoria. El uso clásico confirma significados de pasar completamente desapercibido u olvidar enteramente. La evidencia multilingüe (español «habéis olvidado», francés «oublier», alemán «vergessen») transmite consistentemente la pérdida completa de memoria o conciencia de algo antes conocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1586', 'spa', 'Elegir o seleccionar con un propósito; como participio sustantivado, ''el Elegido'' (título mesiánico).', 'Elegir o seleccionar con un propósito; como participio sustantivado, ''el Elegido'' (título mesiánico).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1587', 'spa', 'Fallar, agotarse, cesar; llegar a su fin o quedar exhausto', 'Compuesto de ἐκ (fuera) y λείπω (dejar), este verbo transmite la idea de que algo se acaba, se extingue o deja de existir. En Lucas 16:9, Jesús aconseja hacerse amigos con las riquezas injustas para que ''cuando falten'' los reciban en las moradas eternas. Lucas 22:32 recoge la oración de Jesús para que la fe de Pedro ''no falte''. Lucas 23:45 lo emplea para la luz del sol que se eclipsa durante la crucifixión. Hebreos 1:12 cita el Salmo 102 para declarar que los años de Dios ''no cesarán''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1588', 'spa', 'Escogido, elegido — seleccionado por Dios para un propósito especial, una relación o un destino escatológico.', 'Escogido, elegido — seleccionado por Dios para un propósito especial, una relación o un destino escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1589', 'spa', 'Eleccion; el acto soberano de Dios al escoger personas o un pueblo para sus propositos redentores.', 'Un sustantivo teologico de gran peso que designa el acto divino de seleccion: la eleccion deliberada de Dios de personas o de un pueblo para cumplir su plan de salvacion. Pablo lo convierte en piedra angular de su argumento en Romanos 9-11: la eleccion no se basa en las obras sino en Aquel que llama (Ro 9:11), un remanente existe ''conforme a la eleccion de gracia'' (Ro 11:5), e Israel sigue siendo amado ''en cuanto a la eleccion'' (Ro 11:28). En Hechos 9:15 el propio Pablo es llamado ''instrumento de eleccion'', y 2 Pedro 1:10 exhorta a los creyentes a hacer firme su vocacion y eleccion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1590', 'spa', 'Desfallecer, desmayar, perder el nimo; agotarse fsica o espiritualmente', 'Describe un estado de agotamiento fsico o desaliento espiritual en el que las fuerzas de una persona se agotan. Jess lo usa en sentido concreto cuando advierte que despedir a la multitud hambrienta hara que desfallecieran en el camino (Mateo 15:32; Marcos 8:3). Pablo y el autor de Hebreos lo aplican a la perseverancia moral y espiritual: los creyentes no deben cansarse de hacer el bien (Glatas 6:9) ni desanimarse bajo la disciplina divina (Hebreos 12:3, 5). El espaol ''desfallecer'' y el francs ''dfaillir'' transmiten ese sentido de agotamiento progresivo de la vitalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1591', 'spa', 'Secar, limpiar o enjugar; se usa para quitar lágrimas, ungüento o agua del cuerpo de alguien.', 'Verbo táctil e íntimo que describe el acto de secar o limpiar algo de una superficie, generalmente del cuerpo de una persona. Cada aparición en el NT involucra un acto devoto de una mujer hacia Jesús o el lavamiento de pies que Jesús hace a sus discípulos. La mujer pecadora seca los pies de Jesús con su cabello tras mojarlos con lágrimas (Lc 7:38, 44), María de Betania hace lo mismo con perfume costoso (Jn 11:2; 12:3), y Jesús seca los pies de sus discípulos con una toalla después de lavárselos (Jn 13:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1592', 'spa', 'burlarse, mofarse, escarnecer, ridiculizar con desprecio', 'Este verbo compuesto significa burlarse, mofarse o ridiculizar con desprecio. Lucas lo usa dos veces: en 16:14 los fariseos se burlan de la enseñanza de Jesús sobre el dinero, y en 23:35 los gobernantes se mofan de Jesús en la cruz. La palabra sugiere ridículo despreciativo, como mirar a alguien por encima del hombro. El compuesto intensifica la idea básica de la burla con particular desdén y escarnio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1593', 'spa', 'Escabullirse, retirarse discretamente; apartarse sin llamar la atención o evadir la observación', 'Este verbo significa escabullirse, apartarse o retirarse discretamente. En Juan 5:13, después de sanar al paralítico, Jesús «se apartó» de la multitud junto al estanque. Originalmente significaba volver la cabeza hacia un lado (como un caballo que sacude la cabeza) o caer de cabeza, pero desarrolló significados de escabullirse, evitar o retirarse. El uso clásico confirma sentidos de girar la cabeza hacia un lado, rehuir o caer precipitadamente. La evidencia multilingüe (español «se apartó», francés «se dérober», alemán «entweichen») transmite una retirada silenciosa y discreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1594', 'spa', 'Recobrar la sobriedad, volver en sí; recuperar la lucidez tras la embriaguez, literal o metafóricamente', 'Este verbo significa recobrar la sobriedad o volver en sí, es decir, recuperarse de un estado de embriaguez, o metafóricamente despertar espiritualmente y pensar con claridad. En 1 Corintios 15:34, Pablo ordena: «Despertad a la justicia y dejad de pecar.» Aunque puede referirse literalmente a la recuperación tras la embriaguez, aquí se usa metafóricamente: despierten espiritualmente, piensen con lucidez. El uso clásico confirma significados de dormir la borrachera o recuperarse de estados emocionales. La evidencia multilingüe (español «despertad», francés «devenir sobre», alemán «nüchtern werden») muestra tanto sobriedad literal como despertar metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1595', 'spa', 'Voluntario, de libre voluntad; hecho por elección propia y no por obligación ni necesidad', 'Este adjetivo describe acciones emprendidas por libre voluntad y no bajo coacción. En el griego clásico distinguía los actos voluntarios de aquellos realizados bajo coerción o ignorancia. Pablo lo emplea en Filemón para enfatizar que cualquier favor que Filemón muestre debe brotar de una voluntad genuina, no de la obligación. La evidencia multilingüe (español «voluntario», francés «volontaire», alemán «freiwillig») destaca consistentemente el elemento de libre elección. El término conlleva peso legal y ético, diferenciando la disposición auténtica del cumplimiento a regañadientes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1596', 'spa', 'voluntariamente, de buena voluntad, por libre albedrío', 'Este adverbio significa voluntariamente o de buena voluntad, enfatizando la libre elección en lugar de la compulsión. Hebreos 10:26 habla de pecar voluntariamente después de recibir el conocimiento de la verdad, mientras 1 Pedro 5:2 insta a los ancianos a pastorear no por obligación sino voluntariamente. La palabra subraya la elección deliberada y la acción voluntaria. Las formas relacionadas en el griego clásico distinguían entre acciones voluntarias e involuntarias, una distinción ética clave.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1597', 'spa', 'desde hace mucho, desde antiguo, hace mucho tiempo', 'Este adverbio temporal significa ''desde hace mucho'' o ''desde antiguo'', enfatizando una duración extendida. 2 Pedro lo usa dos veces: en 2:3 advirtiendo que el juicio para los maestros falsos no ha estado inactivo desde hace mucho, y en 3:5 describiendo la creación hace mucho tiempo por la palabra de Dios. La frase combina ''desde'' (ek) con ''hace mucho'' (palai) para subrayar la antigüedad o realidad de larga data.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1598', 'spa', 'Poner a prueba de modo extremo; tentar a Dios exigiendo señales o pruebas de su poder', 'Forma intensificada de πειράζω (el prefijo ἐκ- añade fuerza), este verbo describe el acto de poner a alguien a prueba de manera presuntuosa, especialmente a Dios. En los relatos sinópticos de la tentación (Mt 4:7; Lc 4:12), Jesús cita Deuteronomio 6:16 contra Satanás: ''No tentarás al Señor tu Dios''. Pablo advierte a los corintios contra repetir las provocaciones de Israel en el desierto (1 Co 10:9). El intérprete de la ley en Lucas 10:25 pone a prueba a Jesús con una pregunta, aunque allí el matiz es más leve.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1599', 'spa', 'enviar, despachar, mandar fuera', 'Este verbo compuesto significa enviar o despachar desde un lugar. Hechos lo usa dos veces en contextos misioneros: en 13:4 el Espíritu Santo envía a Bernabé y a Saulo, y en 17:10 los creyentes envían a Pablo a Berea. El prefijo ''ek-'' enfatiza el movimiento hacia afuera desde un punto de partida. El uso clásico incluía enviar mensajeros, despachar ejércitos, e incluso divorciar a una esposa (enviarla lejos).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1600', 'spa', 'extender, desplegar; estirar las manos en gesto de invitación o súplica', 'Este verbo significa extender o desplegar, y se usa con frecuencia para describir el acto de estirar las manos. En Romanos 10:21, Pablo cita a Isaías para retratar el gesto paciente de Dios hacia Israel: "Todo el día extendí mis manos hacia un pueblo desobediente y rebelde." La imagen evoca tanto la invitación divina como el lamento por el rechazo. Las traducciones en distintas lenguas (extendí, étendre, ausbreiten) captan ese movimiento de apertura y extensión hacia el otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1601', 'spa', 'Caer, desprenderse; encallar (náutico); apartarse de la gracia; fallar, quedar sin efecto. Compuesto de ἐκ (''fuera de'') y πίπτω (''caer''), este verbo t', 'Caer, desprenderse; encallar (náutico); apartarse de la gracia; fallar, quedar sin efecto. Compuesto de ἐκ (''fuera de'') y πίπτω (''caer''), este verbo traza un arco vívido desde lo literal hasta lo teológico. Lucas lo usa cuatro veces en Hechos 27 para la aterradora posibilidad de que un barco encalle en las rocas de Malta, mientras que en Hechos 12:7 las cadenas de Pedro simplemente se caen de sus manos al toque del ángel. Santiago toma prestada la imagen de una flor que pierde sus pétalos para ilustrar lo efímero de la riqueza terrenal (Stg 1:11; cf. 1 P 1:24). Pablo le da su filo teológico más agudo en Gálatas 5:4: quienes buscan justificación por la ley ''han caído de la gracia''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1602', 'spa', 'zarpar, hacerse a la vela, partir navegando; salida marítima desde el puerto para emprender un viaje', 'El verbo ἐκπλέω (de ἐκ + πλέω, ''navegar'') significa zarpar del puerto o alejarse de la costa navegando, el equivalente náutico de partir o emprender un viaje. En Hechos, este verbo marca las transiciones en los desplazamientos misioneros de Pablo entre distintas localidades. Cada travesía no representa un mero detalle logístico, sino un impulso narrativo: nuevos territorios, nuevas audiencias y la obediencia continua a la comisión apostólica a través del mundo mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1603', 'spa', 'cumplir plenamente, completar; llevar algo a su plena realización', 'Este verbo compuesto intensifica el sentido básico de "llenar" para significar llevar algo a su completo cumplimiento. En Hechos 13:33, describe cómo Dios ha cumplido su promesa al resucitar a Jesús de entre los muertos. El tiempo perfecto subraya el estado consumado: la promesa permanece cumplida. Las traducciones multilingües (ha cumplido, accomplir) destacan el aspecto de realización plena, mientras que el alemán preserva la forma griega, reconociendo quizá su riqueza teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1604', 'spa', 'cumplimiento, consumación; acción de llevar algo a su plena realización', 'Este sustantivo designa la consumación o cumplimiento de algo, con frecuencia en un contexto temporal o ritual. En Hechos 21:26 se refiere a la consumación de los días de purificación, es decir, el momento en que los requisitos rituales quedan plenamente satisfechos. En el uso clásico incluye el llenado de medidas o ciclos, y la LXX lo emplea para colmar la medida de los pecados. Aquí marca el punto final de un período ritual, cuando las obligaciones se dan por cumplidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1605', 'spa', 'Asombrarse, quedar atónito, quedar estupefacto — ser golpeado por una sorpresa o admiración abrumadora. ἐκπλήσσω literalmente significa ''golpear fuera', 'Asombrarse, quedar atónito, quedar estupefacto — ser golpeado por una sorpresa o admiración abrumadora. ἐκπλήσσω literalmente significa ''golpear fuera de'' los sentidos, combinando ἐκ (''fuera'') y πλήσσω (''golpear''). En sus 13 apariciones neotestamentarias siempre se presenta en voz pasiva o media, describiendo el asombro abrumador de las multitudes o individuos ante Jesús. La reacción es provocada por su enseñanza (Mt 7:28, 13:54, 22:33; Mr 1:22, 6:2, 11:18; Lc 4:32), su autoridad sobre los demonios (Mr 7:37), y sus acciones en general (Lc 9:43). No se trata de una sorpresa leve sino de un asombro visceral y desorientador — un ser sacudido por lo inesperado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1606', 'spa', 'Exhalar el último aliento, expirar, morir; específicamente el instante fisiológico en que cesa la respiración', 'Este verbo capta el momento fisiológico de la muerte: la última exhalación en la que la vida abandona el cuerpo. Aunque el griego clásico lo empleaba para vientos que cesan o fuegos que se apagan, el Nuevo Testamento lo usa con cruda literalidad para la muerte de Jesús. Tanto Marcos como Lucas escogen esta palabra para describir el instante preciso en que Cristo entregó el espíritu. Marcos la registra dos veces (15:37, 39): primero como narración, luego en la confesión del centurión provocada por cómo murió Jesús. Lucas 23:46 la combina con las últimas palabras de Jesús: «Habiendo dicho esto, expiró». La palabra subraya la realidad humana y física de la muerte de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1607', 'spa', 'Salir o proceder; de la partida física de un lugar y de palabras o espíritu que emanan de una fuente.', 'Salir o proceder; de la partida física de un lugar y de palabras o espíritu que emanan de una fuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1608', 'spa', 'fornicar desenfrenadamente, entregarse a la inmoralidad sexual; practicar conducta sexual ilícita de manera extrema', 'Esta forma intensificada del verbo raíz para inmoralidad sexual aparece en Judas 7, donde describe los graves pecados sexuales de Sodoma y Gomorra. La composición del verbo sugiere un comportamiento extremo y flagrante que traspasa los límites ordinarios. Judas cita su entrega a la inmoralidad como ejemplo admonitorio del juicio divino. Las traducciones multilingües (fornicando, s''étant prostituées, Unzucht treibend) transmiten la gravedad de la transgresión, ya sea mediante el aspecto continuo o un vocabulario intensificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1609', 'spa', 'escupir, rechazar con desprecio; expulsar de la boca con repugnancia', 'Este verbo significa escupir, a menudo como gesto de asco o rechazo. En Gálatas 4:14, Pablo se asombra de que los gálatas no lo despreciaron ni lo rechazaron con repugnancia a pesar de su aflicción física; al contrario, lo recibieron con los brazos abiertos. La expresión evoca un rechazo visceral, la clase de aversión que se muestra ante algo repulsivo. Las traducciones varían: el español enfatiza el rechazo (rechazasteis), mientras que el francés y el alemán preservan la literalidad del "escupir", captando la intensidad física de la metáfora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1610', 'spa', 'Desarraigar, arrancar de raíz; erradicar por completo', 'Tomado del lenguaje agrícola, este verbo describe el acto violento de arrancar una planta de raíz. Jesús lo emplea en la parábola del trigo y la cizaña, advirtiendo contra un desarraigo prematuro que dañaría las buenas plantas (Mt 13:29), y declara que toda planta no plantada por el Padre será desarraigada (Mt 15:13). En Lucas 17:6, hasta una morera obedece la orden de desarraigarse. Judas 1:12 aplica la imagen metafóricamente a los falsos maestros: ''desarraigados, dos veces muertos''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1611', 'spa', 'Asombro, estupefacción abrumadora ante un evento milagroso; trance, estado visionario extático inducido divinamente.', 'Derivado de ἐξίστημι (''desplazar, poner fuera''), el sustantivo ἔκστασις capta la experiencia de ser arrojado fuera del estado mental ordinario, ya sea por asombro o por visión divina. En su uso más frecuente en el NT, denota el asombro absoluto que se apodera de los testigos de lo milagroso: la estupefacción de la multitud cuando la hija de Jairo resucita (Marcos 5:42), el temblor y desconcierto de las mujeres ante el sepulcro vacío (Marcos 16:8), y el pasmo que sobrecoge a los espectadores tras la sanación del cojo en la Puerta Hermosa (Hechos 3:10). Pero Hechos introduce un segundo sentido específicamente revelatorio: Pedro cae en un ''trance'' en la azotea de Jope (Hechos 10:10; 11:5), y Pablo relata haber entrado en ''trance'' mientras oraba en el templo (Hechos 22:17). Aquí ἔκστασις ya no es mero asombro, sino un estado alterado de conciencia en el que Dios comunica visiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1612', 'spa', 'pervertir, torcer, desviar; corromper o distorsionar moral o doctrinalmente', 'Este verbo significa torcer o dar vuelta por completo, y en sentido figurado, pervertir o corromper. En Titus 3:11, describe a alguien que está "pervertido", es decir, torcido fuera de su forma moral y doctrinal correcta. El tiempo perfecto indica un estado establecido: tal persona se ha deformado y permanece así, pecando por su propia condenación. La imagen de torcer o retorcer (en el uso clásico incluye pies vueltos hacia afuera) se convierte en una poderosa representación de la distorsión moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1613', 'spa', 'perturbar, agitar, causar confusión; desestabilizar emocional o socialmente', 'Este verbo significa causar confusión o agitación, ya sea en el plano emocional o social. En Acts 16:20, los acusadores afirman que Pablo y Silas están "perturbando nuestra ciudad", provocando problemas y alterando el orden social. El verbo puede describir tanto conmoción emocional como agitación social. Las traducciones multilingües (perturban, troubler) enfatizan el efecto desestabilizador, mientras que el alemán conserva la forma griega, quizás reconociendo la dimensión legal y social específica de la acusación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1614', 'spa', 'Extender o estirar, especialmente la mano para sanar, ordenar o actuar. Uno de los verbos de accion mas vivos del Nuevo Testamento, asociado casi univ', 'Extender o estirar, especialmente la mano para sanar, ordenar o actuar. Uno de los verbos de accion mas vivos del Nuevo Testamento, asociado casi universalmente con la mano extendida. Jesus extiende su mano para tocar al leproso (Mt 8:3; Mc 1:41; Lc 5:13), ordena al hombre de la mano seca que la extienda y esta es restaurada (Mt 12:13; Mc 3:5; Lc 6:10), y senala ampliamente a sus discipulos como su verdadera familia (Mt 12:49). A Pedro se le dice ''extenderas tus manos'' en profecia de su martirio (Jn 21:18). Un unico uso nautico en Hch 27:30 describe a marineros bajando anclas con pretexto de ''echar'' equipo desde la proa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1615', 'spa', 'terminar, completar, llevar a su fin, acabar', 'Este verbo compuesto significa terminar, completar o llevar algo a su fin. Jesús lo usa dos veces en Lucas 14 en la parábola sobre calcular el costo: el versículo 29 habla de no poder terminar una torre, y el versículo 30 describe la burla cuando uno no puede completarla. El prefijo ''ek-'' intensifica la idea de llevar algo hasta su consumación. El uso clásico incluía completar grandes obras y cumplir promesas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1616', 'spa', 'fervor, celo, diligencia; devoción intensa o persistencia ferviente', 'Este sustantivo denota fervor, celo o devoción ferviente. En Acts 26:7, Pablo describe la adoración de Israel como ejercida "con fervor" (literalmente "en intensidad") noche y día. El término transmite una devoción intensa y sostenida, no una observancia casual. El uso clásico incluye ideas de entusiasmo desbordante o asiduidad. Aquí caracteriza la adoración constante de las doce tribus, resaltando la seriedad con que sirven a Dios en la esperanza de la promesa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1617', 'spa', 'más fervientemente, con mayor intensidad; de manera aún más ardiente en fervor o esfuerzo', 'Este adverbio comparativo intensifica la idea de fervor, describiendo una acción realizada con aún mayor intensidad o ardor. En Luke 22:44, describe a Jesús orando "más intensamente" en Getsemaní, a medida que su angustia se profundizaba. La forma comparativa marca una escalada: su oración se volvió más intensa, más urgente. Las traducciones multilingües (más intensamente, plus ardemment) captan esta creciente intensidad, el aumento del fervor emocional y espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1618', 'spa', 'ferviente, intenso, ardiente; marcado por devoción sostenida y compromiso sincero', 'Este adjetivo describe una devoción ferviente, intensa y ardiente. En 1 Peter 4:8, califica al amor: "amor ferviente los unos por los otros". El término sugiere un amor que se extiende, que es sostenido e inquebrantable, no casual ni intermitente. El uso clásico incluye ideas de apego cálido o asiduidad. Pedro exhorta a un amor que persiste a través de las dificultades, cubriendo multitud de pecados. Las traducciones multilingües (ferviente, eifrig) enfatizan la calidez y diligencia de este amor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1619', 'spa', 'fervientemente, con fervor, intensamente, con celo', 'Este adverbio significa fervientemente, con fervor o con intenso celo. Hechos 12:5 describe a la iglesia orando fervientemente por Pedro encarcelado, y 1 Pedro 1:22 exhorta a los creyentes a amarse unos a otros fervientemente desde el corazón. La palabra enfatiza la intensidad y calidez de la acción, ya sea oración o amor. El adjetivo raíz significaba ''tenso'' o ''extendido'', sugiriendo esfuerzo aplicado e intencionalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1620', 'spa', 'Exponer, presentar en detalle; abandonar (a un niño); exhibir públicamente', 'Verbo compuesto (ἐκ + τίθημι, ''colocar fuera'') con dos sentidos bien diferenciados en Hechos. En Hch 7:21 se refiere a la exposición del niño Moisés, la práctica antigua de abandonar recién nacidos no deseados dejándolos a la intemperie. En Hch 11:4, 18:26 y 28:23 significa exponer o explicar algo de manera ordenada y detallada. El español ''exponer'' abarca ambos registros con naturalidad: la exposición física y la exposición intelectual. El tránsito del sentido literal al retórico sigue una trayectoria semántica esperable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1621', 'spa', 'Sacudir, sacudirse el polvo o la ropa como señal de rechazo o desvinculación', 'Verbo gestual vívido que describe la acción enérgica de sacudirse el polvo o la suciedad. En los Evangelios, Jesús ordena a sus discípulos sacudir el polvo de sus pies al salir de un pueblo que no los reciba, como señal profética de juicio (Mt 10:14; Mc 6:11). Pablo y Bernabé realizan este mismo gesto contra los opositores hostiles en Antioquía de Pisidia (Hch 13:51). En Hch 18:6, Pablo sacude sus vestiduras contra la sinagoga de Corinto, evocando a Nehemías 5:13. Cada uso neotestamentario porta una fuerza simbólica que trasciende el acto físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1622', 'spa', 'Fuera, externo a; excepto, a menos que — adverbio/preposición de exterioridad espacial o exclusión lógica.', 'El adverbio ἐκτός (de ἐκ, «fuera de») señala lo que se encuentra más allá de un límite, ya sea físico o lógico. En su sentido de exclusión introduce excepciones a afirmaciones generales — «excepto», «a menos que», «aparte de» — como cuando Pablo concede que las lenguas sin interpretación no aprovechan nada «a menos que» alguien interprete (1 Co 14:5). En su sentido espacial denota exterioridad física: Jesús dice a los fariseos que limpien «lo de fuera» del vaso (Mt 23:26), y Pablo habla de pecados «fuera» del cuerpo (1 Co 6:18). Los dos sentidos se distinguen con claridad en español: «excepto» frente a «fuera de».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1623', 'spa', 'sexto — adjetivo ordinal que indica la sexta posición en una secuencia. Ἕκτος es el ordinal derivado directamente de ἕξ (''seis''), y sus 14 apariciones', 'sexto — adjetivo ordinal que indica la sexta posición en una secuencia. Ἕκτος es el ordinal derivado directamente de ἕξ (''seis''), y sus 14 apariciones en el Nuevo Testamento se distribuyen entre contextos narrativos y apocalípticos con notable regularidad. En los Evangelios marca la ''hora sexta'' — aproximadamente el mediodía — en momentos cruciales: la oscuridad durante la crucifixión (Mt 27:45, Mc 15:33, Lc 23:44) y el encuentro de Jesús con la samaritana (Jn 4:6). En Apocalipsis puntúa la secuencia de juicios divinos: el sexto sello (Ap 6:12), el sexto ángel con trompeta (Ap 9:13-14) y la sexta copa (Ap 16:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1624', 'spa', 'Desviarse, apartarse o torcerse del camino; alejarse de la sana doctrina o la conducta correcta.', 'Transmite la imagen de salirse de un camino o rumbo, usado casi exclusivamente en las Epístolas Pastorales y Hebreos para referirse a la desviación doctrinal o moral. Algunos se han «desviado» de la fe sincera hacia palabrerías vacías (1 Ti 1:6), otros se han apartado en pos de Satanás (1 Ti 5:15), y a Timoteo se le advierte que evite las profanas pláticas para no «desviarse» (1 Ti 6:20; 2 Ti 4:4). Hebreos 12:13 lo emplea en sentido físico: enderezar las sendas para que el miembro cojo no se «disloque».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1625', 'spa', 'nutrir, criar, alimentar y cuidar', 'Este verbo significa nutrir, criar o educar desde la niñez. Pablo lo usa en Efesios 5:29 de los esposos que nutren a sus esposas como Cristo a la iglesia, y en 6:4 de criar a los hijos en el Señor. La palabra enfatiza el cuidado y la nutrición continuos más que simplemente alimentar. El uso clásico incluía criar niños, criar animales e incluso plantas nutriendo sus raíces.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1626', 'spa', 'nacimiento prematuro, aborto; persona nacida fuera de tiempo o de manera anormal', 'Este sustantivo designa un nacimiento prematuro o fuera de tiempo, a menudo un aborto espontaneo o un nino nacido muerto. En 1 Corintios 15:8, Pablo lo emplea metaforicamente refiriendose a si mismo: "al ultimo de todos, como a un abortivo, se me aparecio tambien a mi." El termino tiene un matiz de autodepreciacion, sugiriendo que su llamado apostolico fue anomalo, fuera de la secuencia normal. Pablo no estuvo entre los Doce durante el ministerio terrenal de Jesus, lo que hizo de su encuentro con el Cristo resucitado algo excepcional y, en cierto sentido, "prematuro" en comparacion con los demas apostoles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1627', 'spa', 'Sacar, llevar fuera — remoción física de un lugar, o producción agrícola de vegetación.', 'El verbo compuesto ἐκφέρω (ἐκ + φέρω, «llevar fuera») abarca el acto de sacar o llevar algo fuera de un espacio cerrado. En su uso más crudo del NT, aparece tres veces en Hechos 5 para referirse al traslado de los cadáveres de Ananías y Safira, un detalle que la iglesia primitiva no olvidaría fácilmente. Más allá del contexto funerario, Jesús lleva al ciego «fuera» de la aldea (Mr 8:23) y ordena que saquen el mejor vestido para el hijo pródigo (Lc 15:22). Un único uso agrícola en Hebreos 6:8 extiende el verbo a la tierra que «produce» espinos y abrojos, pasando del vocabulario de movimiento al de rendimiento productivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1628', 'spa', 'Huir, escapar — evadir un peligro, el juicio divino o la cautividad física.', 'El verbo ἐκφεύγω (ἐκ + φεύγω, «huir fuera») denota una fuga exitosa, ya sea de la ira divina, el peligro espiritual o la cautividad física. Pablo advierte a los que se creen justos que no «escaparán» del juicio de Dios (Ro 2:3), y el autor de Hebreos pregunta cómo escapará quien descuide una salvación tan grande (He 2:3). En el plano físico, Pablo mismo escapó de Damasco siendo descolgado en un canasto por el muro (2 Co 11:33), y el endemoniado que venció a los hijos de Esceva los dejó huyendo desnudos y heridos (Hch 19:16). Ambos sentidos comparten la idea central de librarse de una fuerza amenazante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1629', 'spa', 'aterrorizar, espantar, intimidar; causar gran temor o alarma', 'Este verbo significa asustar o aterrorizar, provocando alarma o intimidacion. En 2 Corintios 10:9, Pablo aclara que no quiere parecer que esta "aterrorizando" a los corintios con sus cartas. Sus epistolas tienen un tono fuerte y contundente, pero el insiste en que no pretende usar el miedo como arma. El verbo transmite la idea de infundir temor o alarma en alguien, a veces de manera deliberada. Las traducciones multilingues (aterrorizar, effrayer, erschrecken) subrayan la produccion de miedo o espanto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1630', 'spa', 'aterrorizado, asustado, lleno de temor', 'Este adjetivo significa aterrorizado o grandemente asustado. Marcos 9:6 lo usa para describir el temor de Pedro en la Transfiguración, y Hebreos 12:21 lo aplica a la reacción aterrorizada de Moisés en el Sinaí. La palabra enfatiza ser arrojado a un estado de temor, a menudo por manifestaciones divinas. El prefijo ''ek-'' intensifica la idea básica de temor, sugiriendo estar fuera de sí por el espanto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1631', 'spa', 'brotar, retoñar, echar brotes, producir crecimiento', 'Este verbo significa brotar, retoñar o producir crecimiento. Ambas apariciones están en la parábola de Jesús sobre la higuera: Mateo 24:32 y Marcos 13:28 hablan del árbol echando hojas como señal del verano cercano. La palabra enfatiza el surgimiento y crecimiento natural. El uso clásico incluía engendrar hijos (para varones), dar a luz (para mujeres) y plantas brotando, con el tiempo perfecto describiendo el estado de haber crecido.');